update public.fields set verification_status='verified_against_standard', verification_quote='Die kritische Regenspende $r_{\text {krit }}$ charakterisiert die Niederschlagsbelastung, für deren Regenwasserabfluss typischerweise zentrale Behandlungsanlagen hydraulisch ausgelegt werden. In der Vergangenheit wurde zumeist $r_{\text {krit }}=15 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ angesetzt. | Für die Bemessung von Regenklärbecken (siehe 6.2) und den Nachweis der Klärbedingung von Durchlaufbecken (siehe 7.2.4.2) wird für $r_{\text {krit }}$ deshalb ein einheitlicher Wert von $15 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ empfohlen. — printed p.79', verification_note='md-verified 2026-09-05 (Anh. B.1.2, printed p.79 — 15 l/(s·ha) is printed as a recommendation („empfohlen"), i.e. standard_range with an engineer selection (SR-2), not a fixed value) [VC]', verified_at=now() where id='442e28a4-e203-4ec0-a66e-4a16e89d33c9' and verification_status not in ('verified_against_standard','corrected');
-- h_Na
update public.fields set verification_status='verified_against_standard', verification_quote='Die Jahresniederschlagshöhe $h_{\mathrm{Na}}$ sollte möglichst von einer ortsnahen Regenstation übernommen werden, die das langjährige Niederschlagsverhalten im Untersuchungsgebiet repräsentiert. Sie kann als stationsspezifischer langjähriger Jahresmittelwert den meteorologischen Jahrbüchern des Deutschen Wetterdienstes oder örtlich verfügbaren, ausreichend langen Niederschlagsaufzeichnungen (nach DWD 30 Jahre) entnommen werden. Darüber hinaus können beim Deutschen Wetterdienst regionalisierte Werte der mittleren Jahresniederschlagshöhe bezogen werden. — printed p.84', verification_note='md-verified 2026-09-05 (Anh. B.3.2.1, printed p.84) [VC]', verified_at=now() where id='9e33f0b4-f0ee-45bb-9a7c-4ed719464d9d' and verification_status not in ('verified_against_standard','corrected');
-- t_f
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $t_{\mathrm{f}}$ & min & Längste Fließzeit bis zum Regenbecken \\ | längste Fließzeit bis zum Regenüberlauf aus unmittelbaren Einzugsgebieten \\ ohne Berücksichtigung der Fließzeit in reinen Transportkanälen — printed p.22, p.55', verification_note='md-verified 2026-09-05 (Tab. 2 p.22 + Gl. (25) legend §7.3.4.5 p.55) [VC]', verified_at=now() where id='ecb50db7-001e-4e94-a723-b9902c1ca2bb' and verification_status not in ('verified_against_standard','corrected');
-- NG_m
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $N G_{\mathrm{m}}$ & 1 & Mittlere Geländeneigungsklasse \\ | Stehen die detaillierten Kanalnetzdaten nicht zur Verfügung, kann die Größe $d \cdot I$ näherungsweise über die flächengewichtete, mittlere Geländeneigungsklasse $N G_{\mathrm{m}}$ abgeschätzt werden. | d \cdot I=0,001 \cdot\left(1+2\left(N G_{\mathrm{m}}-1\right)\right) \quad \text { in } \mathrm{m} \tag{B.18} — printed p.21, p.89', verification_note='md-verified 2026-09-05 (Tab. 2 p.21 + Anh. B.3.3.10 Gl. (B.18) p.89) [VC]', verified_at=now() where id='4b48eb95-9841-402b-a3c8-b0ead6d79ffb' and verification_status not in ('verified_against_standard','corrected');
-- ---------- A1022-08 Kanalnetz- und Kläranlagen-Eingangsdaten ----------
-- Q_M
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $Q_{M}$ & $\mathrm{l} / \mathrm{s}$ & Mischwasserabfluss zur Kläranlage (Bemessungswert) \\ | Der Mischwasserabfluss zur Kläranlage $Q_{M}$ ist eine zentrale Einflussgröße auf das Entlastungsverhalten von Mischsystemen und somit auch für die Ermittlung des erforderlichen Gesamtspeichervolumens. Die zahlenmäßige Festlegung von $Q_{M}$ erfolgt grundsätzlich in Abstimmung mit den Bemes-sungs- und Betriebsdaten der Kläranlage. $Q_{\mathrm{M}}$ berechnet sich nach Arbeitsblatt ATV-DVWK-A 198 gemäß GL. (B.4). | Q_{\mathrm{M}}=f_{\mathrm{S}, \mathrm{QM}} \cdot Q_{\mathrm{S}, \mathrm{aM}}+Q_{\mathrm{F}} \quad \text { in l/s } \tag{B.4} — printed p.21, p.85', verification_note='md-verified 2026-09-05 (Tab. 2 p.21 + Anh. B.3.2.3.1 Gl. (B.4) p.85) [VC]', verified_at=now() where id='62731c79-a6c5-45b1-8f38-94dc6a1e8375' and verification_status not in ('verified_against_standard','corrected');
-- Q_T_aM
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $Q_{\mathrm{T}, \mathrm{aM}}$ & l/s & Trockenwetterabfluss im Jahresmittel \\ | Die Eingangsgrößen I längste Fließzeit im Gesamtgebiet $t_{\mathrm{f}}$; I Trockenwetterabfluss im 24-h-Mittel $Q_{T, \mathrm{aM}}$; I Trockenwetterabfluss als stündlicher Spitzenabfluss $Q_{\mathrm{T}, \mathrm{h}, \max }$; I mittlerer Fremdwasserabfluss $Q_{\text {F,am }}$ und I (flächengewichtete) mittlere Geländeneigungsgruppe $N G_{\mathrm{m}}$ werden entsprechend dem Arbeitsblatt ATV-DVWK-A 198 verwendet. — printed p.21, p.84', verification_note='md-verified 2026-09-05 (Tab. 2 p.21 + Anh. B.3.1 p.84 (value method defers to ATV-DVWK-A 198 — NR for the number itself)) [VC]', verified_at=now() where id='74062673-0820-4a85-aa15-4a7ffb5fc93f' and verification_status not in ('verified_against_standard','corrected');
-- Q_T_h_max
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $Q_{\mathrm{T}, \mathrm{h}, \max }$ & $\mathrm{l} / \mathrm{s}$ & Stündlicher Spitzenwert des Trockenwetterabflusses \\ | Die Eingangsgrößen I längste Fließzeit im Gesamtgebiet $t_{\mathrm{f}}$; I Trockenwetterabfluss im 24-h-Mittel $Q_{T, \mathrm{aM}}$; I Trockenwetterabfluss als stündlicher Spitzenabfluss $Q_{\mathrm{T}, \mathrm{h}, \max }$; I mittlerer Fremdwasserabfluss $Q_{\text {F,am }}$ und I (flächengewichtete) mittlere Geländeneigungsgruppe $N G_{\mathrm{m}}$ werden entsprechend dem Arbeitsblatt ATV-DVWK-A 198 verwendet. — printed p.22, p.84', verification_note='md-verified 2026-09-05 (Tab. 2 p.22 + Anh. B.3.1 p.84) [VC]', verified_at=now() where id='69086214-16e0-4338-8d34-700e203f3e0b' and verification_status not in ('verified_against_standard','corrected');
-- Q_F
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $Q_{F}$ & l/s & Fremdwasserabfluss \\ | Zur Problematik des Fremdwassers und der sachgerechten Ermittlung der Abflussgrößen wird auf das Merkblatt DWA-M 182 verwiesen. Dabei sind die je nach Kanalart (Schmutz-, Misch-, Regenwasserkanäle) unterschiedlichen Fremdwasserarten zu beachten. — printed p.21, p.80', verification_note='md-verified 2026-09-05 (Tab. 2 p.21 + Anh. B.1.4 p.80 — the determination method defers to DWA-M 182 (NR for the value)) [VC]', verified_at=now() where id='9aee502a-d946-4472-abd9-c9f4c7bd5e1d' and verification_status not in ('verified_against_standard','corrected');
-- Q_R_Tr
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $Q_{\mathrm{R}, \mathrm{Tr}}$ & $\mathrm{l} / \mathrm{s}$ & Regenwasserabfluss aus Trenngebieten \\ | Liegen keine Messungen vor, ist mit einem Zuschlag von $100 \%$ des maximal stündlichen Schmutzwasserabflusses $Q_{S, h, \text { max }, \text { Tr }}$ zu rechnen (GL. B.6). | Q_{\mathrm{R}, \mathrm{Tr}}=Q_{\mathrm{S}, \mathrm{~h}, \mathrm{max}, \mathrm{Tr}} \quad \text { in } \mathrm{l} / \mathrm{s} \tag{B.6} — printed p.21, p.86', verification_note='md-verified 2026-09-05 (Tab. 2 p.21 + Anh. B.3.2.4 Gl. (B.6) p.86) [VC]', verified_at=now() where id='36524ae5-b6dd-4ea8-ada6-5da27d9dd2fa' and verification_status not in ('verified_against_standard','corrected');
-- C_T_aM_CSB
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $\mathrm{C}_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}$ & mg/l & CSB-Konzentration im Trockenwetterabfluss (Jahresmittelwert) \\ | Die Verschmutzung des Trockenwetterabflusses wird bei der Ermittlung des Gesamtspeichervolumens nach 7.3.2 über den Jahresmittelwert des CSB im Zulauf zur Vorklärung der Kläranlage aus Messungen bestimmt (siehe Arbeitsblatt ATV-DVWK-A 198). Sind im Einzugsgebiet SchmutzwasserEinleitungen mit höheren Konzentrationen vorhanden, zum Beispiel stark verschmutztes betriebliches Schmutzwasser, müssen die erhöhten Konzentrationswerte bei der Ermittlung des Gesamtspeichervolumens sowie bei der Bemessung betroffener Regenentlastungsbauwerke (siehe 7.3.4) und im Nachweisverfahren nach 8.4 berücksichtigt werden. — printed p.22, p.86', verification_note='md-verified 2026-09-05 (Tab. 2 p.22 + Anh. B.3.2.5 p.86) [VC]', verified_at=now() where id='7519144e-3d78-4db5-a8ca-8baabe5e00e0' and verification_status not in ('verified_against_standard','corrected');
-- C_R_CSB
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $C_{\mathrm{R}, \mathrm{CSB}}$ & mg/l & CSB-Konzentration im Regenwasserabfluss (Jahresmittelwert) \\ | Im Bezugslastfall des Berechnungsgangs zur Ermittlung des erforderlichen Gesamtspeichervolumens wird die mittlere CSB-Konzentration im Regenwasserabfluss einheitlich mit $107 \mathrm{mg} / \mathrm{l}$ vorgegeben. — printed p.22, p.87', verification_note='md-verified 2026-09-05 (Tab. 2 p.22 + Anh. B.3.2.7 p.87 — 107 mg/l is the printed Bezugslastfall value) [VC]', verified_at=now() where id='dd81269c-d507-4d93-9050-2f0f9c91a037' and verification_status not in ('verified_against_standard','corrected');
-- C_KA_CSB
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $C_{\text {KA,CSB }}$ & mg/l & CSB-Konzentration im Kläranlagenablauf (Rechenwert) \\ | Die Konzentration $C_{\text {KA,AFS63 }}$ wird im Kontext dieses Arbeitsblatts als Standardwert mit $15 \mathrm{mg} / \mathrm{l}$ berücksichtigt, die Konzentration $C_{K A, C S B}$ einheitlich mit $70 \mathrm{mg} / \mathrm{l}$. — printed p.22, p.81', verification_note='md-verified 2026-09-05 (Tab. 2 p.22 + Anh. B.1.5 p.81 — 70 mg/l printed as einheitlicher Standardwert) [VC]', verified_at=now() where id='fa947904-afc4-4e7c-b992-d65e9cedf30a' and verification_status not in ('verified_against_standard','corrected');
-- d_I
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $d_{\mathrm{i}}$ & m & Kanaldurchmesser bzw. Breite einzelner Kanalhaltungen \\ \hline $d \cdot I_{\mathrm{s}}$ & m & Einflussfaktor zur Bewertung von Kanalablagerungen \\ | \hline $I_{\mathrm{s}}$ & 1 & Sohlengefälle von Kanalhaltungen \\ \hline $l_{\mathrm{i}}$ & m & Länge von Kanalhaltungen \\ | Angesichts der allgemeinen Verfügbarkeit detaillierter Kanalnetzdaten wird empfohlen, den Einflusswert der Kanalablagerungen $a_{\mathrm{a}}$ direkt über die Kennwerte der Kanäle im Einzugsgebiet zu ermitteln. Dazu wird $d \cdot I$ als längengewichtetes Produkt aus Durchmesser $d$ (Breite bei Nichtkreisprofilen) und Sohlengefälle $I_{\mathrm{S}}$ der einzelnen Kanäle ermittelt: — printed p.24, p.89', verification_note='md-verified 2026-09-05 (Tab. 2 p.24 + Anh. B.3.3.10 p.89) [VC]', verified_at=now() where id='2a5c2295-79f8-4fbd-8fba-425947254cd2' and verification_status not in ('verified_against_standard','corrected');
-- f_S_QM
