-- Q_S_aM
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $Q_{\mathrm{S}, \mathrm{aM}}$ & l/s & Schmutzwasserabfluss im Jahresmittel \\ | Der Mischwasserabfluss zur Kläranlage $Q_{M}$ ist eine zentrale Einflussgröße auf das Entlastungsverhalten von Mischsystemen und somit auch für die Ermittlung des erforderlichen Gesamtspeichervolumens. Die zahlenmäßige Festlegung von $Q_{M}$ erfolgt grundsätzlich in Abstimmung mit den Bemes-sungs- und Betriebsdaten der Kläranlage. $Q_{\mathrm{M}}$ berechnet sich nach Arbeitsblatt ATV-DVWK-A 198 gemäß GL. (B.4). | Q_{\mathrm{M}}=f_{\mathrm{S}, \mathrm{QM}} \cdot Q_{\mathrm{S}, \mathrm{aM}}+Q_{\mathrm{F}} \quad \text { in l/s } \tag{B.4} — printed p.21, p.85', verification_note='md-verified 2026-09-05 (Tab. 2 p.21 + Anh. B.3.2.3.1 Gl. (B.4) p.85) [VC]', verified_at=now() where id='2fc68f68-e7aa-4732-81d0-ff92c0dcdcb6' and verification_status not in ('verified_against_standard','corrected');
-- Q_M_i
update public.fields set verification_status='verified_against_standard', verification_quote='Für jedes Teileinzugsgebiet können das erforderliche Speichervolumen und der maßgebende Drosselabfluss gesondert ermittelt werden. Die Summe der Mischwasserabflüsse $Q_{M, i}$ der Teilgebiete darf zu keinem Zeitpunkt den Bemessungswert der Kläranlage bei Mischwasserabfluss $\left(Q_{M}\right)$ überschreiten: | \sum Q_{M, i} \leq Q_{M} \quad \text { in l/s } \tag{B.5} — printed p.85', verification_note='md-verified 2026-09-05 (Anh. B.3.2.3.3 Gl. (B.5), printed p.85) [VC]', verified_at=now() where id='f431c5fb-96a6-41f3-84a0-c95e6d383071' and verification_status not in ('verified_against_standard','corrected');
-- Q_S_h_max_Tr
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $Q_{\mathrm{S}, \mathrm{h}, \text { max }, \mathrm{Tr}}$ & $\mathrm{l} / \mathrm{s}$ & Schmutzwasserabfluss in/aus Trenngebieten (stündlicher Spitzenwert) \\ | Liegen keine Messungen vor, ist mit einem Zuschlag von $100 \%$ des maximal stündlichen Schmutzwasserabflusses $Q_{S, h, \text { max }, \text { Tr }}$ zu rechnen (GL. B.6). | Q_{\mathrm{R}, \mathrm{Tr}}=Q_{\mathrm{S}, \mathrm{~h}, \mathrm{max}, \mathrm{Tr}} \quad \text { in } \mathrm{l} / \mathrm{s} \tag{B.6} — printed p.21, p.86', verification_note='md-verified 2026-09-05 (Tab. 2 p.21 + Anh. B.3.2.4 Gl. (B.6) p.86) [VC]', verified_at=now() where id='2b2130e1-f6e3-49b3-8b2e-9fe00de80a54' and verification_status not in ('verified_against_standard','corrected');
-- ---------- A1022-09 Abminderungswert f_D (Anhang C) ----------
-- f_D
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $f_{\mathrm{D}}$ & 1 & Abminderungswert „durchlässig befestigte Flächen“ (siehe 7.2, Anhang B, B.3.2.2 und Anhang C) \\ | Die zusätzliche abflussmindernde Wirkung durchlässiger Flächenbefestigungen sowie von Flach- und Gründächern im gesamten Spektrum entlastungsrelevanter Regenereignisse wird im Berechnungsgang für das erforderliche Gesamtspeichervolumen und bei der Berechnung des kritischen Regenabflusses $Q_{\mathrm{R}, \text { krit }}$ (siehe B.1.3) über den Abminderungswert $f_{\mathrm{D}}$ berücksichtigt. | Sofern keine detaillierten Erhebungen der unterschiedlichen Flächenarten und -befestigungen bzw. entsprechende Abflussmessungen vorliegen, ist der Abminderungswert 1,0 zu verwenden. — printed p.24, p.84', verification_note='md-verified 2026-09-05 (Tab. 2 p.24 + Anh. B.3.2.2 p.84 — printed default 1,0 when no survey exists; values per Tab. C.1 p.91) [VC]', verified_at=now() where id='0c41f726-d046-4364-864f-f510fa1fa18a' and verification_status not in ('verified_against_standard','corrected');
-- oberflaechentyp
update public.fields set verification_status='verified_against_standard', verification_quote='\caption{Tabelle C.1: Empfohlene Abminderungswerte $f_{\mathrm{D}}$ für Dachflächen und Flächenbeläge mit erhöhtem Rückhalt von Niederschlagswasser (siehe B.3.2.2)} | \hline Flächentyp & Art der Befestigung & $f_{\mathrm{D}}$ \\ \hline \multirow[t]{2}{*}{Schrägdach} & Metall, Glas, Schiefer, Faserzement, & 1,0 \\ \hline & Ziegel, Dachpappe & 1,0 \\ | \hline \multirow[t]{2}{*}{Gründach (Neigung bis $15^{\circ}$ oder ca. $25 \%$ )} & humusiert < 10 cm Aufbau & 0,8 \\ \hline & humusiert $\geq 10 \mathrm{~cm}$ Aufbau & 0,6 \\ | \hline & Rasengittersteine & 0,4 \\ — printed p.91', verification_note='md-verified 2026-09-05 (Anh. C Tab. C.1, printed p.91 — the printed Flächentyp/Befestigung list is a closed set; encoded here as free text (see STAGED)) [VC]', verified_at=now() where id='bf4d8f57-4410-4198-80f4-3a53e4039975' and verification_status not in ('verified_against_standard','corrected');
