-- ---------- A1022-11 Erforderlicher Wirkungsgrad η_erf ----------
-- eta_erf
update public.fields set verification_status='verified_against_standard', verification_quote='Der erforderliche Wirkungsgrad der Behandlungsmaßnahmen ergibt sich nach GL. (6): | \eta_{\text {erf }}=\operatorname{Max}\left(0 ; 1-b_{R, e, z u l, A F S 63} / b_{R, a, A F S 63}\right) & \quad(-) \text { bzw } . \\ \eta_{\text {erf }}=\operatorname{Max}\left(0 ; 1-b_{R, e, z u l, A F 63} / b_{R, a, A F S 63}\right) \cdot 100 & \text { in } \% \tag{6} | $\eta_{\text {erf }}$ & (-) oder $\%$ & erforderlicher Wirkungsgrad der Behandlungsmaßnahme \\ $b_{\mathrm{R}, \mathrm{e}, \mathrm{zu}, \mathrm{AFS} 63}$ & $\mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$ & zulässiger flächenspezifischer Stoffaustrag AFS63 — printed p.34', verification_note='md-verified 2026-09-05 (§5.2.3.2 Gl. (6), printed p.34) [VC]', verified_at=now() where id='1691c314-3a3b-4df7-b811-b5849c0565a2' and verification_status not in ('verified_against_standard','corrected');
-- b_R_e_zul_AFS63
update public.fields set verification_status='verified_against_standard', verification_quote='Mit den Festlegungen in 5.2.1 zur Flächenkategorisierung und grundsätzlichen Behandlungsbedürftigkeit der Kategorien II und III wird der für Belastungskategorie I abgeleitete flächenspezifische Stoffabtrag von $280 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$ als zulässiger flächenspezifischer Stoffaustrag („Emission“) für AFS63 zur Einleitung von Regenwasserabflüssen in Oberflächengewässer als Rechenwert definiert ( $=b_{\mathrm{R}, \mathrm{e}, \mathrm{zu}, \mathrm{AFS} 63}$ ). — printed p.33', verification_note='md-verified 2026-09-05 (§5.2.2.4, printed p.33) [VC]', verified_at=now() where id='fef35d5a-9be7-4052-9a9d-d05065447ed9' and verification_status not in ('verified_against_standard','corrected');
-- b_R_a_AFS63_ref
update public.fields set verification_status='verified_against_standard', verification_quote='Der resultierende flächenspezifische Stoffabtrag des betrachteten Gebiets ergibt sich zu: | b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63}=B_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63} / \Sigma A_{\mathrm{b}, \mathrm{a}, \mathrm{i}}=B_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63} / A_{\mathrm{b}, \mathrm{a}} \quad \text { in } \mathrm{kg} /(\mathrm{ha} \cdot \mathrm{a}) \tag{5} | b_{\text {R, } \mathrm{a}, \text { AF663 }} \quad \mathrm{kg} /(\text { ha ⋅ } \mathrm{a}) \quad \text { flächenspezifischer Stoffabtrag AFS63 des betrachteten Gebiets } — printed p.34', verification_note='md-verified 2026-09-05 (§5.2.3.2 Gl. (5), printed p.34 — cross-worksheet reference to A1022-10.b_R_a_AFS63) [VC]', verified_at=now() where id='a2f2dbbe-e70f-4fcc-872e-e77f725d1373' and verification_status not in ('verified_against_standard','corrected');
