-- ---------- A1022-13 Kritischer Regenabfluss Q_R,krit ----------
-- Q_R_krit
update public.fields set verification_status='verified_against_standard', verification_quote='Der kritische Regenwasserabfluss $Q_{\mathrm{R}, \mathrm{krit}}$ bezeichnet entsprechend B.1.2 die Größe des Regenwasserabflusses, der einer Behandlung zugeführt wird. Er berechnet sich über die gewählte kritische Regenspende $r_{\text {krit }}$ und die angeschlossene befestigte Fläche $A_{\mathrm{b}, \mathrm{a}}$ des direkten Einzugsgebiets der Behandlungsanlage: | Q_{\mathrm{R}, \text { krit }}=r_{\text {krit }} \cdot A_{\mathrm{b}, \mathrm{a}} \cdot f_{\mathrm{D}} \quad \text { in } \mathrm{l} / \mathrm{s} \tag{B.1} — printed p.80', verification_note='md-verified 2026-09-05 (Anh. B.1.3 Gl. (B.1), printed p.80) [VC]', verified_at=now() where id='cfa62ac1-0c29-496d-8b4f-2027792315bd' and verification_status not in ('verified_against_standard','corrected');
-- A_b_a_ref
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $A_{\mathrm{b}, \mathrm{a}}$ & ha & Angeschlossene befestigte Fläche (in Bezug auf Regenwasserabfluss); vereinfachte Schreibweise für $A_{\mathrm{E}, \mathrm{k}, \mathrm{b}, \mathrm{a}}$, siehe Bild 1 in 4.2.3 \\ — printed p.21', verification_note='md-verified 2026-09-05 (Tab. 2 p.21 — cross-worksheet reference to A1022-05) [VC]', verified_at=now() where id='370d6afe-edfa-45ed-9737-c8bfc8a31449' and verification_status not in ('verified_against_standard','corrected');
-- f_D_ref
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $f_{\mathrm{D}}$ & 1 & Abminderungswert „durchlässig befestigte Flächen“ (siehe 7.2, Anhang B, B.3.2.2 und Anhang C) \\ — printed p.24', verification_note='md-verified 2026-09-05 (Tab. 2 p.24 — cross-worksheet reference to A1022-09) [VC]', verified_at=now() where id='190daf28-12b5-440a-914e-521132bcfaba' and verification_status not in ('verified_against_standard','corrected');
-- r_krit_ref
update public.fields set verification_status='verified_against_standard', verification_quote='Die kritische Regenspende $r_{\text {krit }}$ charakterisiert die Niederschlagsbelastung, für deren Regenwasserabfluss typischerweise zentrale Behandlungsanlagen hydraulisch ausgelegt werden. In der Vergangenheit wurde zumeist $r_{\text {krit }}=15 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ angesetzt. | Für die Bemessung von Regenklärbecken (siehe 6.2) und den Nachweis der Klärbedingung von Durchlaufbecken (siehe 7.2.4.2) wird für $r_{\text {krit }}$ deshalb ein einheitlicher Wert von $15 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ empfohlen. — printed p.79', verification_note='md-verified 2026-09-05 (Anh. B.1.2 p.79 — cross-worksheet reference to A1022-07) [VC]', verified_at=now() where id='f6170dd6-5cb0-4230-b785-f9c6c3e412cd' and verification_status not in ('verified_against_standard','corrected');
-- ---------- A1022-14 Bemessungszufluss Q_Bem,Tr ----------
-- Q_Bem_Tr
update public.fields set verification_status='verified_against_standard', verification_quote='Der Bemessungszufluss $Q_{\text {Bem, Tr }}$ bestimmt die maximale hydraulische Belastung der Behandlungsanlage im Trennverfahren und damit den Anteil des der Behandlung zugeführten Regenwasserabflussvolumens. Er errechnet sich abhängig von der gewählten kritischen Regenspende $r_{\text {krit }}$ als Summe des kritischen Regenabflusses $Q_{\mathrm{R}, \text { krit }}$ und des maßgebenden Fremdwasserabflusses $Q_{\mathrm{F}}$ zu: | Q_{\mathrm{Bem}, \mathrm{Tr}}=Q_{\mathrm{R}, \text { krit }}+Q_{\mathrm{F}} \quad \text { in } \mathrm{l} / \mathrm{s} \tag{B.2} — printed p.82', verification_note='md-verified 2026-09-05 (Anh. B.2.1 Gl. (B.2), printed p.82) [VC]', verified_at=now() where id='9dda87b6-905e-4736-9666-ab1640713db0' and verification_status not in ('verified_against_standard','corrected');
-- Q_F_ref
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $Q_{F}$ & l/s & Fremdwasserabfluss \\ | Der Bemessungszufluss $Q_{\text {Bem, Tr }}$ bestimmt die maximale hydraulische Belastung der Behandlungsanlage im Trennverfahren und damit den Anteil des der Behandlung zugeführten Regenwasserabflussvolumens. Er errechnet sich abhängig von der gewählten kritischen Regenspende $r_{\text {krit }}$ als Summe des kritischen Regenabflusses $Q_{\mathrm{R}, \text { krit }}$ und des maßgebenden Fremdwasserabflusses $Q_{\mathrm{F}}$ zu: | Q_{\mathrm{Bem}, \mathrm{Tr}}=Q_{\mathrm{R}, \text { krit }}+Q_{\mathrm{F}} \quad \text { in } \mathrm{l} / \mathrm{s} \tag{B.2} — printed p.21, p.82', verification_note='md-verified 2026-09-05 (Tab. 2 p.21 + Anh. B.2.1 p.82 — cross-worksheet reference to A1022-08) [VC]', verified_at=now() where id='b8e8ec28-1e2f-4477-964e-b3129746e473' and verification_status not in ('verified_against_standard','corrected');
-- Q_R_krit_ref
update public.fields set verification_status='verified_against_standard', verification_quote='Der kritische Regenwasserabfluss $Q_{\mathrm{R}, \mathrm{krit}}$ bezeichnet entsprechend B.1.2 die Größe des Regenwasserabflusses, der einer Behandlung zugeführt wird. Er berechnet sich über die gewählte kritische Regenspende $r_{\text {krit }}$ und die angeschlossene befestigte Fläche $A_{\mathrm{b}, \mathrm{a}}$ des direkten Einzugsgebiets der Behandlungsanlage: | Q_{\mathrm{R}, \text { krit }}=r_{\text {krit }} \cdot A_{\mathrm{b}, \mathrm{a}} \cdot f_{\mathrm{D}} \quad \text { in } \mathrm{l} / \mathrm{s} \tag{B.1} — printed p.80', verification_note='md-verified 2026-09-05 (Anh. B.1.3 p.80 — cross-worksheet reference to A1022-13) [VC]', verified_at=now() where id='eb304553-e5d1-4188-a326-a2cecfc180e2' and verification_status not in ('verified_against_standard','corrected');
-- ---------- A1022-15 Oberflächenbeschickung q_A,Bem ----------
-- q_A_Bem
update public.fields set verification_status='verified_against_standard', verification_quote='Die Oberflächenbeschickung $q_{\mathrm{A}}$ bestimmt maßgeblich den erreichbaren Grad des Feststoffrückhalts in Sedimentationsanlagen. Der Bemessungswert $q_{\mathrm{A}, \mathrm{Bem}}$ der Oberflächenbeschickung ist die hydraulische Beschickung beim Bemessungszufluss $Q_{\text {Bem, Tr. }}$ Er berechnet sich nach GI. (B.3) zu: | q_{\mathrm{A}, \text { Bem }}=3,6 \cdot Q_{\text {Bem }, \mathrm{Tr}} / A_{\text {sed }} \text { in } \mathrm{m} / \mathrm{h} \tag{B.3} | $A_{\text {sed }} \quad$ in $\mathrm{m}^{2} \quad$ sedimentationswirksame Oberfläche der Sedimentationsanlage — printed p.82', verification_note='md-verified 2026-09-05 (Anh. B.2.2 Gl. (B.3), printed p.82) [VC]', verified_at=now() where id='27ab3670-164a-47e6-98cd-ea438385420c' and verification_status not in ('verified_against_standard','corrected');
-- A_sed
update public.fields set verification_status='verified_against_standard', verification_quote='Die Oberflächenbeschickung $q_{\mathrm{A}}$ bestimmt maßgeblich den erreichbaren Grad des Feststoffrückhalts in Sedimentationsanlagen. Der Bemessungswert $q_{\mathrm{A}, \mathrm{Bem}}$ der Oberflächenbeschickung ist die hydraulische Beschickung beim Bemessungszufluss $Q_{\text {Bem, Tr. }}$ Er berechnet sich nach GI. (B.3) zu: | q_{\mathrm{A}, \text { Bem }}=3,6 \cdot Q_{\text {Bem }, \mathrm{Tr}} / A_{\text {sed }} \text { in } \mathrm{m} / \mathrm{h} \tag{B.3} | $A_{\text {sed }} \quad$ in $\mathrm{m}^{2} \quad$ sedimentationswirksame Oberfläche der Sedimentationsanlage — printed p.82', verification_note='md-verified 2026-09-05 (Anh. B.2.2 Gl. (B.3) + legend, printed p.82; Tab. 2 p.23 gives the unit m²) [VC]', verified_at=now() where id='2aa850ed-3347-487b-98c6-c0b93faf6aa2' and verification_status not in ('verified_against_standard','corrected');
-- q_A_max
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $q_{\mathrm{A}, \max }$ & $\mathrm{m} / \mathrm{h}$ & Maximale Oberflächenbeschickung von Sedimentationsanlagen \\ | Bei der Bemessung von Sedimentationsanlagen stellt die maximale Oberflächenbeschickung $q_{\mathrm{A}, \max }$ lauch bei einer Sedimentationskammer mit Schrägklärerelementen) eine wichtige Kenngröße dar. Auch wenn die Sedimentationswirkung bei einer großen Anzahl von kleinen Ereignissen mit sehr geringen Oberflächenbeschickungen deutlich unterhalb von $q_{\mathrm{A}, \max }$ liegt, bestimmt $q_{\mathrm{A}, \max }$ durch die Begrenzung des Remobilisierungspotenzials maßgeblich den erreichbaren mittleren jährlichen Wirkungsgrad. — printed p.23, p.82', verification_note='md-verified 2026-09-05 (Tab. 2 p.23 + Anh. B.2.3 p.82) [VC]', verified_at=now() where id='399d0235-35fe-4d96-804d-04be6b2d5a69' and verification_status not in ('verified_against_standard','corrected');
-- q_A_b
update public.fields set verification_status='verified_against_standard', verification_quote='Für bestehende Anlagen, die mit davon abweichendem $r_{\text {krit }}$ bemessen wurden, kann der maßgebende Gesamtwirkungsgrad näherungsweise über die Oberflächenbeschickung $q_{\mathrm{A}, \mathrm{b}}$, abgeleitet aus der bei der Bemessungsregenspende auftretenden maximalen Oberflächenbeschickung $q_{\mathrm{A}, \max }$ nach GL. (9), abgeschätzt werden. | q_{\mathrm{A}, \mathrm{~b}}=q_{\mathrm{A}, \max } \cdot 15 / r_{\text {krit }} \quad \text { in } \mathrm{m} / \mathrm{h} \tag{9} | q_{\mathrm{A}, \mathrm{~b}} \quad \mathrm{~m} / \mathrm{h} \quad \text { maßgebende Oberflächenbeschickung im Bestand } — printed p.41', verification_note='md-verified 2026-09-05 (§6.2.2 Gl. (9), printed p.41) [VC]', verified_at=now() where id='beb405fd-6c8f-4d90-b465-9f549902a595' and verification_status not in ('verified_against_standard','corrected');
-- ---------- A1022-16 Sedimentationswirkungsgrad η_sed ----------
-- eta_sed
update public.fields set verification_status='verified_against_standard', verification_quote='I Der Sedimentationswirkungsgrad $\eta_{\text {sed }}$ bezeichnet den Anteil der in die Sedimentationsanlage eingetragenen Stofffracht, der dort infolge Sedimentation abgeschieden wird. | \caption{Tabelle B.1: Oberflächenbeschickungsklassen und Sedimentationswirkungsgrade für AFS63 (Quelle: Fuchs \& Kemper 2018)} | \hline $q_{\mathrm{A}, \max }$ in m/h & $\eta_{\text {sed }}$ in \% & Anzahl der Ereignisse \\ \hline 0,5 bis 1 & 61 \% & 13 \\ \hline 1,1 bis 2 & 52 \% & 6 \\ \hline 2,1 bis 4 & 41 \% & 13 \\ \hline 4,1 bis 6 & 24 \% & 7 \\ \hline 6,1 bis 8 & 34 \% & 1 \\ \hline 8,1 bis > 10 & 13 \% & 5 \\ — printed p.63, p.83', verification_note='md-verified 2026-09-05 (§8.3.1.2 p.63 + Tab. B.1 p.83; printed unit is %, encoded unit is dimensionless (see STAGED)) [VC]', verified_at=now() where id='e7a84075-c85a-4a35-9983-bf933cf80484' and verification_status not in ('verified_against_standard','corrected');
-- q_A_max_lookup
update public.fields set verification_status='verified_against_standard', verification_quote='\caption{Tabelle B.1: Oberflächenbeschickungsklassen und Sedimentationswirkungsgrade für AFS63 (Quelle: Fuchs \& Kemper 2018)} | \hline $q_{\mathrm{A}, \max }$ in m/h & $\eta_{\text {sed }}$ in \% & Anzahl der Ereignisse \\ \hline 0,5 bis 1 & 61 \% & 13 \\ \hline 1,1 bis 2 & 52 \% & 6 \\ \hline 2,1 bis 4 & 41 \% & 13 \\ \hline 4,1 bis 6 & 24 \% & 7 \\ \hline 6,1 bis 8 & 34 \% & 1 \\ \hline 8,1 bis > 10 & 13 \% & 5 \\ — printed p.83', verification_note='md-verified 2026-09-05 (Anh. B.2.3 Tab. B.1, printed p.83 — the class bounds 0,5..>10 m/h are the printed lookup axis) [VC]', verified_at=now() where id='ca601de3-ea6f-4d7c-a91f-992ad48348fe' and verification_status not in ('verified_against_standard','corrected');
-- ---------- A1022-17 Gesamtwirkungsgrad η_ges ----------
-- eta_ges
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Auswahl und Auslegung der Behandlungsanlage ist der nach 5.2.3.2 erforderliche Stoffrückhalt maßgebend. Der Gesamtwirkungsgrad $\eta_{\text {ges }}$ muss mindestens dem erforderlichen Wirkungsgrad $\eta_{\text {erf }}$ nach (GL. 6) entsprechen. | Bild 4: Gesamtwirkungsgrade $\boldsymbol{\eta}_{\text {ges }}$ von Regenklärbecken für AFS63 in Abhängigkeit von der in der Bemessung zugrunde liegenden maximalen Oberflächenbeschickung $q_{\mathrm{A}, \mathrm{Bem}}, r_{\text {krit }}=15 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$, Beckentiefe 2 m (Quelle: Schmitt 2018) — printed p.40, p.41', verification_note='md-verified 2026-09-05 (§6.2.2 p.40 + Bild 4 p.41; η_ges itself is read off Bild 4 — a curve, no printed equation) [VC]', verified_at=now() where id='7adbe3f4-f7f4-4c7e-a23c-f47dcc05aa8c' and verification_status not in ('verified_against_standard','corrected');
-- q_A_Bem_for_eta
