-- ---------- A1022-18 Bemessung Regenklärbecken (A_RKB, V_RKB) und Schrägklärer (A_eff) ----------
-- A_RKB
update public.fields set verification_status='verified_against_standard', verification_quote='Die erforderliche sedimentationswirksame Oberfläche leitet sich aus dem Bemessungszufluss und der nach Bild 4 erforderlichen Oberflächenbeschickung $q_{\mathrm{A}, \mathrm{Bem}} \mathrm{ab}$, mit der der maßgebende Gesamtwirkungsgrad $\eta_{\text {ges }}$ erzielt wird. Die Beckenoberfläche $A_{\text {RKB }}$ berechnet sich nach GL. (10) | A_{\text {RKB }}=3,6 \cdot Q_{\text {Bem }, \text { Tr }} / q_{\text {A,Bem }} \quad \text { in } \mathrm{m}^{2} \tag{10} — printed p.42', verification_note='md-verified 2026-09-05 (§6.2.3 Gl. (10), printed p.42) [VC]', verified_at=now() where id='ae962702-4498-4686-932c-dd6ee2a9bddb' and verification_status not in ('verified_against_standard','corrected');
-- V_RKB
update public.fields set verification_status='verified_against_standard', verification_quote='Hinweise zur konstruktiven Gestaltung von Regenklärbecken enthält das Arbeitsblatt DWA-A 166. In Ergänzung dazu wird für Regenklärbecken aus hydraulisch-konstruktiven Gründen eine Mindesttiefe von 2 m empfohlen. Damit resultiert das erforderliche Speichervolumen nach GL. (11): | V_{\text {RKB }}=A_{\text {RKB }} \cdot h_{\text {RKB }} \quad \text { in m }{ }^{3} \tag{11} — printed p.42', verification_note='md-verified 2026-09-05 (§6.2.4 Gl. (11), printed p.42) [VC]', verified_at=now() where id='705a02b4-2796-4653-a100-0935dce4a0d9' and verification_status not in ('verified_against_standard','corrected');
-- h_RKB
update public.fields set verification_status='verified_against_standard', verification_quote='Hinweise zur konstruktiven Gestaltung von Regenklärbecken enthält das Arbeitsblatt DWA-A 166. In Ergänzung dazu wird für Regenklärbecken aus hydraulisch-konstruktiven Gründen eine Mindesttiefe von 2 m empfohlen. Damit resultiert das erforderliche Speichervolumen nach GL. (11): | \section*{$h_{\text {RKB }} \quad \mathrm{m} \quad$ Tiefe des Regenklärbeckens} — printed p.42', verification_note='md-verified 2026-09-05 (§6.2.4, printed p.42 — 2 m is printed as a recommendation („empfohlen"), not a hard minimum) [VC]', verified_at=now() where id='e131958b-ee67-4bc1-b4ca-801f047d032a' and verification_status not in ('verified_against_standard','corrected');
-- A_eff
update public.fields set verification_status='verified_against_standard', verification_quote='Für Schrägklärer ist die sedimentationswirksame Oberfläche $A_{\text {eff }}$ der Einbauten (.,Sedimentationskör- per") maßgebend. Die erforderliche Oberfläche $A_{\text {eff }}$ berechnet sich nach GL. (12): | A_{\mathrm{eff}}=3,6 \cdot Q_{\mathrm{Bem}, \mathrm{Tr}} / q_{\mathrm{A}, \max } \quad \text { in } \mathrm{m}^{2} \tag{12} | $A_{\text {eff }} \quad \mathrm{m}^{2} \quad$ sedimentationswirksame Oberfläche des Sedimentationskörpers — printed p.43', verification_note='md-verified 2026-09-05 (§6.3 Gl. (12), printed p.43) [VC]', verified_at=now() where id='fc608d56-da1c-429c-85e4-4396f524ab66' and verification_status not in ('verified_against_standard','corrected');
