update public.fields set verification_status='verified_against_standard', verification_quote='In Mischsystemen errechnet sich der für die Bemessung maßgebende Regenabfluss im Drosselabfluss zur Kläranlage $Q_{R, D r}$ aus der Differenz zwischen dem Mischwasserabfluss $Q_{M}$, dem Trockenwetterabfluss $Q_{\text {T,am }}$ und dem Regenabfluss aus Trenngebieten $Q_{\text {R, Tr }}$ entsprechend GL. (B.7): | Q_{R, D r}=Q_{M}-Q_{T, a M}-Q_{R, T r} \quad \text { in l/s } \tag{B.7} — printed p.87', verification_note='md-verified 2026-09-05 (Anh. B.3.3.1 Gl. (B.7), printed p.87) [VC]', verified_at=now() where id='e83d1ee8-0c11-4b12-9a20-8f501829f549' and verification_status not in ('verified_against_standard','corrected');
-- q_R_Dr
update public.fields set verification_status='verified_against_standard', verification_quote='Abweichend von Arbeitsblatt ATV-DVWK-A 198:2003 ist die Regenabflussspende $q_{\text {R,Dr }}$ im Kontext des Berechnungsverfahrens zum erforderlichen Gesamtspeichervolumen definiert als Quotient aus dem Regenabfluss im Drosselabfluss $Q_{R, D r}$ und der angeschlossenen befestigten Fläche $A_{b, a}$ (GL. B.8). | q_{\mathrm{R}, \mathrm{Dr}}=Q_{\mathrm{R}, \mathrm{Dr}} / A_{\mathrm{b}, \mathrm{a}} \quad \text { in l/(s•ha) } \tag{B.8} — printed p.87', verification_note='md-verified 2026-09-05 (Anh. B.3.3.2 Gl. (B.8), printed p.87; the 2 l/(s·ha) validity bound of Gl. (B.12) is printed in B.3.3.5 p.88) [VC]', verified_at=now() where id='2b7408d7-8dd7-41f2-bd68-f4031f6333fb' and verification_status not in ('verified_against_standard','corrected');
