-- ---------- A1022-22 Mittlerer Regenabfluss bei Entlastung Q_R,e ----------
-- Q_R_e
update public.fields set verification_status='verified_against_standard', verification_quote='Dividiert man das Jahresentlastungsvolumen eines Überlaufbauwerks ( $V_{\text {e, Mwü }}$ ) durch die zugehörige Gesamtdauer der Entlastungsereignisse ( $D_{\mathrm{e}}$ ), erhält man als Rechenwert einen mittleren Entlastungsabfluss aus dem Bauwerk. Gleichzeitig fließt durch die Drossel während des Überlaufvorgangs der Regenanteil $Q_{R, D r} \mathrm{ab}$. Beide Abflüsse zusammen ergeben den mittleren Regenwasserabfluss $Q_{R, e}$ während aller Entlastungsereignisse im Laufe eines Jahres nach GL. (B.11): | Q_{R, e}=V_{e, \mathrm{MWÜ}} /\left(D_{e} \cdot 3,6\right)+Q_{R, \mathrm{Dr}} \quad \text { in l/s } \tag{B.11} — printed p.88', verification_note='md-verified 2026-09-05 (Anh. B.3.3.5 Gl. (B.11), printed p.88) [VC]', verified_at=now() where id='df3ce90c-16d2-4d43-9c42-6980ef883d4c' and verification_status not in ('verified_against_standard','corrected');
-- V_e_MWUe
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $V_{\text {e,MWÜ }}$ & $\mathrm{m}^{3} / \mathrm{a}$ & Jahresentlastungsvolumen an Mischwasserüberläufen \\ | $V_{\text {e,MWÜ }}$ & $\mathrm{m}^{3} / \mathrm{a}$ & Jahresentlastungsvolumen an Mischwasserüberläufen \\ $D_{\mathrm{e}}$ & $\mathrm{h} / \mathrm{a}$ & in einem Jahr aufsummierte Überlaufdauer — printed p.22, p.88', verification_note='md-verified 2026-09-05 (Tab. 2 p.22 + Anh. B.3.3.5 Gl. (B.11) legend p.88) [VC]', verified_at=now() where id='e4fab943-efd6-48dc-abef-07ec6a078c9f' and verification_status not in ('verified_against_standard','corrected');
