update public.fields set verification_status='verified_against_standard', verification_quote='\hline $m$ & 1 & mittleres Mischverhältnis \\ \hline $m_{\mathrm{RU}}$ & 1 & Mindestmischverhältnis an Regenüberläufen \\ | Das mittlere Mischverhältnis $m$ zwischen Regenwasser- und Trockenwetterabfluss während aller Entlastungsereignisse ergibt sich nach GI. (B.13) als Verhältnis aus dem mittleren Regenwasserabfluss während sämtlicher Entlastungsereignisse eines Jahres $Q_{R, e}$, zuzüglich dem Regenwasserabfluss aus Trenngebieten $Q_{\mathrm{R}, \mathrm{Tr}}$ und dem gleichzeitig zufließenden mittleren Trockenwetterabfluss $Q_{\mathrm{T}, \mathrm{aM}}$. | m=\left(Q_{\mathrm{R}, \mathrm{e}}+Q_{\mathrm{R}, \mathrm{Tr}}\right) / Q_{\mathrm{T}, \mathrm{aM}} \tag{B.13} — printed p.24, p.88', verification_note='md-verified 2026-09-05 (Tab. 2 p.24 + Anh. B.3.3.6 Gl. (B.13) p.88) [VC]', verified_at=now() where id='98480f2b-5937-4197-a1bc-8453a83e213c' and verification_status not in ('verified_against_standard','corrected');
