-- ---------- A1022-24 Einflusswerte a_c,CSB, a_h, a_a ----------
-- a_c_CSB
update public.fields set verification_status='verified_against_standard', verification_quote='Bei CSB-Konzentrationen im Trockenwetterabfluss $C_{\mathrm{T}, \mathrm{am}, \mathrm{CSB}}$ über $600 \mathrm{mg} / \mathrm{l}$, wird dies durch den Einflussfaktor $a_{\mathrm{c}, \mathrm{CSB}}$ als „Starkverschmutzungszuschlag“ entsprechend GL. (B.15) bei der Berechnung der Bemessungskonzentration $C_{\mathrm{b}, \text { CSB }}$ berücksichtigt: | a_{\mathrm{c}, \mathrm{CSB}}=1 \quad \text { für } \quad C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}} \leq 600 \mathrm{mg} / \mathrm{l} \tag{B.15a} | a_{\mathrm{c}, \mathrm{CSB}}=C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}} / 600 \quad \text { für } \quad C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}>600 \mathrm{mg} / \mathrm{l} \tag{B.15b} — printed p.88', verification_note='md-verified 2026-09-05 (Anh. B.3.3.8 Gl. (B.15a/b), printed p.88) [VC]', verified_at=now() where id='069c6e59-e4d8-45c0-be69-3bb891cd2056' and verification_status not in ('verified_against_standard','corrected');
-- a_h
update public.fields set verification_status='verified_against_standard', verification_quote='Dieser Einfluss wird in der Bemessungskonzentration $C_{\mathrm{b}, \text { CSB }}$ über den Einflusswert $a_{\mathrm{h}}$ berücksichtigt. Der Einflusswert $a_{\mathrm{h}}$ ergibt sich aus GL. (B.16). | a_{\mathrm{h}}=h_{\mathrm{Na}} / 800-1 & \text { für } & 600 \leq h_{\mathrm{Na}} \leq 1.000 \mathrm{~mm} \tag{B.16}\\ a_{\mathrm{h}}=-0,25 & \text { für } & h_{\mathrm{Na}}<600 \mathrm{~mm} \\ a_{\mathrm{h}}=+0,25 & \text { für } & h_{\mathrm{Na}}>1.000 \mathrm{~mm} — printed p.89', verification_note='md-verified 2026-09-05 (Anh. B.3.3.9 Gl. (B.16), printed p.89) [VC]', verified_at=now() where id='12586623-92c9-43b7-9858-141b83a6312d' and verification_status not in ('verified_against_standard','corrected');
-- a_a
update public.fields set verification_status='verified_against_standard', verification_quote='Der Einflusswert $a_{\mathrm{a}}$ berechnet sich über die Größe $d \cdot I$ und die Zwischenwerte $x_{\mathrm{a}}$ und $\tau$ wie folgt: | & x_{\mathrm{a}}=24 \cdot Q_{\mathrm{T}, \mathrm{aM}} / Q_{\mathrm{T}, \mathrm{~h}, \max } \tag{B.19}\\ & \tau=430 \cdot\left(q_{\mathrm{T}, \mathrm{aM}} / f_{\mathrm{D}}\right)^{0,45} \cdot(d \cdot I) \tag{B.20}\\ & a_{\mathrm{a}}=\left(24 / x_{\mathrm{a}}\right)^{2} \cdot(2-\tau) / 10 ; a_{\mathrm{a}} \geq 0 \tag{B.21} — printed p.89', verification_note='md-verified 2026-09-05 (Anh. B.3.3.10 Gl. (B.19)–(B.21), printed p.89) [VC]', verified_at=now() where id='ad272c6e-3ad4-4937-bc6b-9942274e23a8' and verification_status not in ('verified_against_standard','corrected');
