update public.fields set verification_status='verified_against_standard', verification_quote='Der Konzentrationswert $C_{\mathrm{b}, \text { CSB }}$ berücksichtigt nach einem empirischen Ansatz entsprechend GI. (B.14) den Einfluss der projektbezogenen Kenngrößen Jahresniederschlagshöhe $h_{\mathrm{Na}}$ lim Wertebereich $600 \mathrm{~mm} / \mathrm{a} \leq h_{\mathrm{Na}} \leq 1.200 \mathrm{~mm} / \mathrm{a}$ ) und der CSB-Konzentration im Trockenwetterabfluss (für $C_{\mathrm{T}, \mathrm{am}, \mathrm{CSB}}> 600 \mathrm{mg} / \mathrm{ll}$ sowie der Kanalablagerungen auf das Entlastungsverhalten: | C_{\mathrm{b}, \text { CSB }}=600 \cdot\left(a_{\mathrm{c}, \text { CSB }}+a_{\mathrm{h}}+a_{\mathrm{a}}\right) \quad \text { in } \mathrm{mg} / \mathrm{l} \tag{B.14} — printed p.88', verification_note='md-verified 2026-09-05 (Anh. B.3.3.7 Gl. (B.14), printed p.88; Tab. 2 p.22 gives the unit mg/l) [VC]', verified_at=now() where id='0797ff36-3b15-4827-9b83-e4e73f460f9a' and verification_status not in ('verified_against_standard','corrected');
