-- ---------- A1022-26 Flächenspez. Stoffabtrag b_R,a,AFS63 und Einflusswert a_R,AFS63 ----------
-- a_R_AFS63
update public.fields set verification_status='verified_against_standard', verification_quote='Der Anpassungswert $a_{\mathrm{R}, \mathrm{AFS} 63}$ berechnet sich nach GI. (21), begrenzt auf maximal 1,20: | a_{R, A F S 63}=1,0 & \text { für } & b_{R, a, A F S 63} \leq 478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a}) \\ a_{R, A F S 63}=\operatorname{Min}\left(b_{R, a, A F S 63} / 478 ; 1,20\right) & \text { für } & b_{R, a, A F S 63}>478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a}) \tag{21b} | Der Einflusswert $a_{\mathrm{R}, \mathrm{AFS} 63}$ wird auf einen Maximalwert von 1,20 begrenzt. Dieser Wert wird bei einer flächenspezifischen Abtragsfracht $b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63}$ von ca. $570 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$ erreicht. — printed p.49, p.90', verification_note='md-verified 2026-09-05 (§7.3.2.2 Gl. (21a/b) p.49 = Anh. B.3.3.12 Gl. (B.23a/b) p.90; cap 1,20 printed) [VC]', verified_at=now() where id='12edc409-5fc4-4ec8-9669-a93a2e996f65' and verification_status not in ('verified_against_standard','corrected');
-- b_R_a_AFS63
update public.fields set verification_status='verified_against_standard', verification_quote='Der flächenspezifische Stoffabtrag $b_{\text {R,a,AFS63 }}$ errechnet sich projektbezogen aus dem Ergebnis der für das Einzugsgebiet durchgeführten Flächenkategorisierung mit den Rechenwerten nach 5.2.2.3 (Tabelle 4) und den Flächenanteilen $p \mathrm{I}$ bis $p \mathrm{III}$ in \% nach GL. (B.22): | b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63}=(p \mathrm{I} \cdot 280+p \mathrm{II} \cdot 530+p \mathrm{III} \cdot 760) / 100 \quad \text { in } \mathrm{kg} /(\mathrm{ha} \cdot \mathrm{a}) \tag{B.22} — printed p.90', verification_note='md-verified 2026-09-05 (Anh. B.3.3.11 Gl. (B.22), printed p.90) [VC]', verified_at=now() where id='2efaf1ce-eb5b-40f0-b6ce-620838e7c70d' and verification_status not in ('verified_against_standard','corrected');
-- p_I_ref
update public.fields set verification_status='verified_against_standard', verification_quote='Die Flächenanteile der Belastungskategorien I bis III an der gesamt angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}, p_{\mathrm{l}}, p_{\mathrm{ll}}$ und $p_{\mathrm{ll}}$, ermitteln sich entsprechend 5.2.1. Sie werden zur Berechnung der mittleren Konzentration im Regenwasserabfluss $C_{R, A F 563}$ zur Berücksichtigung erhöhter Verschmutzungen des | Regenwasserabflusses über den Einflusswert $a_{\mathrm{R}, \mathrm{AFS} 63}$ bei der Ermittlung des Gesamtspeichervolumens benötigt (siehe B.3.3.12). — printed p.86', verification_note='md-verified 2026-09-05 (Anh. B.3.2.6 p.86 — cross-worksheet reference to A1022-05) [VC]', verified_at=now() where id='084b55ec-4dd3-45d3-af54-5e4b29a55425' and verification_status not in ('verified_against_standard','corrected');
