-- ---------- A1022-27 Mittlere Entlastungskonzentration C_e,CSB ----------
-- C_e_CSB
update public.fields set verification_status='verified_against_standard', verification_quote='Die Mischrechnung zur Bestimmung der mittleren Entlastungskonzentration $C_{\mathrm{e}, \mathrm{CSB}}$ im Überlaufvolumen erfolgt mit der Bemessungskonzentration $C_{b, \text { CSB }}$ in Bezug auf den Trockenwetterabfluss, die mittlere Verschmutzung des Regenwasserabflusses $C_{\text {R,CSB }}$, den Einflusswert $a_{\text {R,AFS63 }}$ und das mittlere Mischverhältnis m nach GL. (B.24): | C_{\mathrm{e}, \mathrm{CSB}}=\left(C_{\mathrm{R}, \mathrm{CSB}} \cdot a_{\mathrm{R}, \mathrm{AFS} 63} \cdot m+C_{\mathrm{b}, \mathrm{CSB}}\right) /(m+1) \quad \text { in } \mathrm{mg} / \mathrm{l} \tag{B.24} — printed p.90', verification_note='md-verified 2026-09-05 (Anh. B.3.3.13 Gl. (B.24) = §7.3.2.2 Gl. (20), printed p.90) [VC]', verified_at=now() where id='594eb3be-c21a-4a99-8145-0c20aa11cd4b' and verification_status not in ('verified_against_standard','corrected');
-- C_R_CSB
update public.fields set verification_status='verified_against_standard', verification_quote='Im Bezugslastfall des Berechnungsgangs zur Ermittlung des erforderlichen Gesamtspeichervolumens wird die mittlere CSB-Konzentration im Regenwasserabfluss einheitlich mit $107 \mathrm{mg} / \mathrm{l}$ vorgegeben. — printed p.87', verification_note='md-verified 2026-09-05 (Anh. B.3.2.7 p.87 — 107 mg/l printed Bezugslastfall value; duplicate of A1022-08.C_R_CSB (see STAGED)) [VC]', verified_at=now() where id='acc14378-1cfc-4cfa-a121-c595c5583880' and verification_status not in ('verified_against_standard','corrected');
