-- m_ref
update public.fields set verification_status='verified_against_standard', verification_quote='Das mittlere Mischverhältnis $m$ zwischen Regenwasser- und Trockenwetterabfluss während aller Entlastungsereignisse ergibt sich nach GI. (B.13) als Verhältnis aus dem mittleren Regenwasserabfluss während sämtlicher Entlastungsereignisse eines Jahres $Q_{R, e}$, zuzüglich dem Regenwasserabfluss aus Trenngebieten $Q_{\mathrm{R}, \mathrm{Tr}}$ und dem gleichzeitig zufließenden mittleren Trockenwetterabfluss $Q_{\mathrm{T}, \mathrm{aM}}$. | m=\left(Q_{\mathrm{R}, \mathrm{e}}+Q_{\mathrm{R}, \mathrm{Tr}}\right) / Q_{\mathrm{T}, \mathrm{aM}} \tag{B.13} — printed p.88', verification_note='md-verified 2026-09-05 (Anh. B.3.3.6 p.88 — cross-worksheet reference to A1022-23) [VC]', verified_at=now() where id='02b202aa-c572-4bc4-bc50-bab620840f70' and verification_status not in ('verified_against_standard','corrected');
