update public.fields set verification_status='verified_against_standard', verification_quote='\hline $V_{\text {R,aM }}$ & $\mathrm{m}^{3} / \mathrm{a}$ & Jahresregenwasserabflussvolumen (langjähriger Mittelwert) \\ | $V_{\text {R,am }}$ berechnet sich aus der Jahresniederschlagshöhe $h_{\mathrm{Na}}$ und dem Jahresabflussbeiwert $\psi_{\mathrm{aM}}$ in Bezug auf die angeschlossene befestigte Fläche $A_{\mathrm{b}, \mathrm{a}}$ nach Gl. (2). | V_{\mathrm{R}, \mathrm{aM}}=h_{\mathrm{Na}}(\mathrm{~mm} / \mathrm{a}) \cdot A_{\mathrm{b}, \mathrm{a}}(\mathrm{ha}) \cdot \psi_{\mathrm{aM}}(-) \cdot 10 \quad \text { in m}^{3} / \mathrm{a} \tag{2} — printed p.22, p.29', verification_note='md-verified 2026-09-05 (Tab. 2 p.22 + §4.3.3 Gl. (2) p.29 — cross-worksheet reference to A1022-05; printed unit is m³/a, encoded unit is m³ (see STAGED)) [VC]', verified_at=now() where id='7390d198-f194-435d-9394-a5ab6e92c1c7' and verification_status not in ('verified_against_standard','corrected');
-- V_R_aM
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $V_{\text {R,aM }}$ & $\mathrm{m}^{3} / \mathrm{a}$ & Jahresregenwasserabflussvolumen (langjähriger Mittelwert) \\ | Die Entlastungsrate $e_{0}$ ist als volumenbezogene Größe über Gl. (13) definiert als Quotient des Jahresentlastungsvolumens an Mischwasserüberläufen ( $V_{e, \text { MWü }}$ ) und des Jahresregenwasserabflussvolumens ( $V_{\text {R,aM }}$ ) in Prozent. | e_{0}=V_{\mathrm{e}, \mathrm{MWU}} / V_{\mathrm{R}, \mathrm{aM}} \cdot 100 \text { in \% } \tag{13} — printed p.22, p.48', verification_note='md-verified 2026-09-05 (Tab. 2 p.22 + §7.3.2.2 Gl. (13) p.48; duplicate of A1022-05.V_R_aM (see STAGED)) [VC]', verified_at=now() where id='846ecde5-5146-4c50-beeb-2ed0d67dcbbc' and verification_status not in ('verified_against_standard','corrected');
-- B_R_e
update public.fields set verification_status='verified_against_standard', verification_quote='Sie erlaubt die Bilanzierung des jährlichen Stoffaustrags durch Mischwasserüberläufe und den Regenwasseranteil im Kläranlagenablauf in Verbindung mit der mittleren Entlastungskonzentration $C_{\mathrm{e}}$ und den Bezug auf den zulässigen Stoffaustrag gemäß GI. (14): | B_{R, e}=\left(V_{R, a M} \cdot e_{0} \cdot C_{e}+V_{R, a M} \cdot\left(100-e_{0}\right) \cdot C_{K A}\right) / 100 \leq B_{R, e, z u l} \quad \text { in } \mathrm{kg} / \mathrm{a} \tag{14} | \hline $B_{\mathrm{R}, \mathrm{e}}$ & kg/a & resultierender Stoffaustrag durch Regenwasserabflüsse \\ — printed p.48', verification_note='md-verified 2026-09-05 (§7.3.2.2 Gl. (14) + legend row, printed p.48) [VC]', verified_at=now() where id='8807ca72-9bb9-4f01-bc34-2b7b48e67e27' and verification_status not in ('verified_against_standard','corrected');
