-- ---------- A1022-33 Gesamtübersicht — bauwerksbezogene Nachweise ----------
-- Q_Dr_minimum
update public.fields set verification_status='verified_against_standard', verification_quote='Der mindestens weiterzuführende Abfluss $Q_{\mathrm{Dr}}$ vor Anspringen der Entlastung als „kritischer Mischwasserabfluss $Q_{\text {krit }}{ }^{\prime \prime}$ ergibt sich aus den maßgebenden Abflusswerten im Direkteinzugsgebiet des Regenüberlaufs und allen oberhalb liegenden Drosselabflüssen nach GL. (26). | Q_{\mathrm{Dr}} \geq Q_{\mathrm{T}, \mathrm{aM}}+Q_{\mathrm{R}, \mathrm{krit}}+\sum Q_{\mathrm{Dr}, \mathrm{i}} \quad \text { in } \mathrm{l} / \mathrm{s} \tag{26} | Der Mindestdrosselabfluss errechnet sich aus Gl. (25) zu: | Q_{\mathrm{Dr}} \geq\left(m_{\mathrm{RU}}+1\right) \cdot Q_{\mathrm{T}, \mathrm{aM}} \quad \text { in l/s } \tag{28} | Dieser Wert ist maßgebend, wenn er den Wert nach GL. (26) übersteigt. — printed p.55', verification_note='md-verified 2026-09-05 (§7.3.4.5 Gl. (26) and Gl. (28), printed p.55) [VC]', verified_at=now() where id='964af6fb-2dc6-4798-b39e-9a80f0c066a7' and verification_status not in ('verified_against_standard','corrected');
-- m_Rue
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $m$ & 1 & mittleres Mischverhältnis \\ \hline $m_{\mathrm{RU}}$ & 1 & Mindestmischverhältnis an Regenüberläufen \\ | Für den nach GL. (26) ermittelten Drosselabfluss ist das Mindestmischverhältnis $m_{\mathrm{RU}}$ nachzuweisen. Der dafür maßgebende Wert m errechnet sich abhängig von der Verschmutzung des Trockenwetter- abflusses analog 7.3.4.2. Ergibt sich bei Anspringen des Überlaufs zwischen Regen- und Trockenwetteranteil im kritischen Mischwasserabfluss nach GI. (27) ein kleineres Mischverhältnis ( $m_{\mathrm{Ru}}<m$ ) ist der Drosselabfluss entsprechend GL. (28) zu erhöhen. | m_{\mathrm{RU}}=\left(Q_{\mathrm{Dr}}-Q_{\mathrm{T}, \mathrm{aM}}\right) / Q_{\mathrm{T}, \mathrm{aM}} \tag{27} — printed p.24, p.55', verification_note='md-verified 2026-09-05 (Tab. 2 p.24 + §7.3.4.5 Gl. (27) p.55) [VC]', verified_at=now() where id='59917f98-eb20-4cf0-983e-648e9e1c18b5' and verification_status not in ('verified_against_standard','corrected');
-- r_krit_calc
update public.fields set verification_status='verified_against_standard', verification_quote='Die kritische Regenspende $r_{\text {krit }}$ errechnet sich in Abhängigkeit der Fließzeit im Direkteinzugsgebiet des Regenüberlaufs nach GL. (25a/b) zu | r_{\text {krit }}=15 \cdot 120 /\left(t_{\mathrm{f}}+120\right) \quad \text { in l/(s.ha) für } \quad t_{\mathrm{f}} \leq 120 \mathrm{~min} \tag{25a} | r_{\text {krit }}=7,5 \quad \text { in l/(s•ha) } \quad \text { für } \quad t_{\mathrm{f}}>120 \mathrm{~min} \tag{25b} — printed p.54', verification_note='md-verified 2026-09-05 (§7.3.4.5 Gl. (25a/b), printed p.54) [VC]', verified_at=now() where id='9541b955-0f03-4f79-bcc3-9b84d8e96060' and verification_status not in ('verified_against_standard','corrected');
