-- ---------- A1022-34 Nachweis: Stoffabtrag AFS63 (Trennsystem) ----------
-- nachweis_AFS_tr_pass
update public.fields set verification_status='verified_against_standard', verification_quote='Überschreitet der flächenspezifische Stoffabtrag $b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63}$ den zulässigen Wert $b_{\mathrm{R}, \mathrm{e}, \mathrm{zu}, \mathrm{AFS} 63}$ nach 5.2.2.4, werden dezentrale oder/und zentrale Behandlungsmaßnahmen erforderlich. In beiden Fällen ist die Wirksamkeit der Behandlungsmaßnahmen über anerkannte Wirkungsgrade zu quantifizieren und in der Bilanzierung zu berücksichtigen (siehe auch Abschnitt 8 „Anwendung von Nachweisverfahren“). | Für die Auswahl und Auslegung der Behandlungsanlage ist der nach 5.2.3.2 erforderliche Stoffrückhalt maßgebend. Der Gesamtwirkungsgrad $\eta_{\text {ges }}$ muss mindestens dem erforderlichen Wirkungsgrad $\eta_{\text {erf }}$ nach (GL. 6) entsprechen. — printed p.34, p.40', verification_note='md-verified 2026-09-05 (§5.2.3.2 p.34 + §6.2.2 p.40 — the two printed criteria the boolean aggregates) [VC]', verified_at=now() where id='6431350b-1b38-403c-978f-c9512305c796' and verification_status not in ('verified_against_standard','corrected');
-- ---------- A1022-35 Nachweis: Gesamtspeichervolumen (Mischsystem) ----------
-- V_s_max_economic
update public.fields set verification_status='verified_against_standard', verification_quote='Ein erforderliches spezifisches Gesamtspeichervolumen von $40 \mathrm{~m}^{3} /$ ha (bezogen auf $A_{\mathrm{b}, \mathrm{a}}$ bzw. den mit $f_{\mathrm{D}}$ abgeminderten Wert) stellt im Allgemeinen aus wasserwirtschaftlichen wie wirtschaftlichen Gründen eine Obergrenze dar. Wird aus der Berechnung ein höherer Wert erforderlich, sind die Ursachen hierfür aufzuzeigen und nach Möglichkeit zu beheben, zum Beispiel durch Reduzierung hoher Fremdwasserzuflüsse. — printed p.51', verification_note='md-verified 2026-09-05 (§7.3.3.1, printed p.51 — 40 m³/ha is printed as an „im Allgemeinen" Obergrenze, not an absolute cap: §8.4.4.2 explicitly carries the calculation on with the higher volume) [VC]', verified_at=now() where id='f063707a-1070-4978-a202-edb2cb839464' and verification_status not in ('verified_against_standard','corrected');
-- nachweis_Vs_min_pass
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Vermeidung von Inkonsistenzen bei besonderen Konstellationen der Eingangsdaten wird für das spezifische Gesamtspeichervolumen als Referenzwert für das fiktive Zentralbecken in Tabelle 6 ein Mindestwert $V_{\mathrm{S}, \text { min }}$ von $5 \mathrm{~m}^{3} /($ hal vorgegeben. — printed p.50', verification_note='md-verified 2026-09-05 (§7.3.2.3, printed p.50) [VC]', verified_at=now() where id='fba976d1-92e7-440e-8006-0cabc1f337bb' and verification_status not in ('verified_against_standard','corrected');
-- nachweis_Vs_max_pass
update public.fields set verification_status='verified_against_standard', verification_quote='Ein erforderliches spezifisches Gesamtspeichervolumen von $40 \mathrm{~m}^{3} /$ ha (bezogen auf $A_{\mathrm{b}, \mathrm{a}}$ bzw. den mit $f_{\mathrm{D}}$ abgeminderten Wert) stellt im Allgemeinen aus wasserwirtschaftlichen wie wirtschaftlichen Gründen eine Obergrenze dar. Wird aus der Berechnung ein höherer Wert erforderlich, sind die Ursachen hierfür aufzuzeigen und nach Möglichkeit zu beheben, zum Beispiel durch Reduzierung hoher Fremdwasserzuflüsse. — printed p.51', verification_note='md-verified 2026-09-05 (§7.3.3.1, printed p.51 — printed as an economic guide value, so a warn-class check (see STAGED)) [VC]', verified_at=now() where id='5090bf46-55db-4c56-9f2f-5e1e620f1179' and verification_status not in ('verified_against_standard','corrected');
-- ---------- A1022-36 Nachweis: Mindestmischverhältnis m ----------
-- m_min_required
update public.fields set verification_status='verified_against_standard', verification_quote='Für jedes Regenüberlaufbecken ist zu überprüfen, ob im langjährigen Mittel ein Mindestmischverhältnis $m$ nach GL. (22) eingehalten wird. Liegt die mittlere CSB-Konzentration im Trockenwetterabfluss über $600 \mathrm{mg} / \mathrm{l}$, ist das Mindestmischverhältnis m nach Gl. (23) zu erhöhen. | m \geq 7 & \text { für } & C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}} \leq 600 \mathrm{mg} / \mathrm{l} \\ m \geq\left(C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}-180\right) / 60 & \text { für } & C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}>600 \mathrm{mg} / \mathrm{l} \tag{23} — printed p.53', verification_note='md-verified 2026-09-05 (§7.3.4.2 Gl. (22)/(23), printed p.53) [VC]', verified_at=now() where id='4c406003-ceae-41cf-8a3c-255b7ad326ad' and verification_status not in ('verified_against_standard','corrected');
-- nachweis_m_pass
update public.fields set verification_status='verified_against_standard', verification_quote='Für jedes Regenüberlaufbecken ist zu überprüfen, ob im langjährigen Mittel ein Mindestmischverhältnis $m$ nach GL. (22) eingehalten wird. Liegt die mittlere CSB-Konzentration im Trockenwetterabfluss über $600 \mathrm{mg} / \mathrm{l}$, ist das Mindestmischverhältnis m nach Gl. (23) zu erhöhen. | m \geq 7 & \text { für } & C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}} \leq 600 \mathrm{mg} / \mathrm{l} \\ m \geq\left(C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}-180\right) / 60 & \text { für } & C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}>600 \mathrm{mg} / \mathrm{l} \tag{23} — printed p.53', verification_note='md-verified 2026-09-05 (§7.3.4.2 Gl. (22)/(23), printed p.53) [VC]', verified_at=now() where id='9a46609b-ef67-401c-8aff-15fba8377498' and verification_status not in ('verified_against_standard','corrected');
-- C_T_aM_CSB_ref
update public.fields set verification_status='verified_against_standard', verification_quote='\hline $\mathrm{C}_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}$ & mg/l & CSB-Konzentration im Trockenwetterabfluss (Jahresmittelwert) \\ | Für jedes Regenüberlaufbecken ist zu überprüfen, ob im langjährigen Mittel ein Mindestmischverhältnis $m$ nach GL. (22) eingehalten wird. Liegt die mittlere CSB-Konzentration im Trockenwetterabfluss über $600 \mathrm{mg} / \mathrm{l}$, ist das Mindestmischverhältnis m nach Gl. (23) zu erhöhen. | m \geq 7 & \text { für } & C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}} \leq 600 \mathrm{mg} / \mathrm{l} \\ m \geq\left(C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}-180\right) / 60 & \text { für } & C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}>600 \mathrm{mg} / \mathrm{l} \tag{23} — printed p.22, p.53', verification_note='md-verified 2026-09-05 (Tab. 2 p.22 + §7.3.4.2 p.53 — cross-worksheet reference to A1022-08) [VC]', verified_at=now() where id='e8e765b2-7644-4ebd-ba88-c9d730fec948' and verification_status not in ('verified_against_standard','corrected');
-- m
update public.fields set verification_status='verified_against_standard', verification_quote='Die bauwerksbezogene Ermittlung des mittleren Mischverhältnisses $m$ im Nachweisverfahren ist in 8.4.5.1 beschrieben. In Bezug auf Einzelbauwerke kann es mit den bauwerksbezogenen Kenngrößen nach GL. (24) abgeschätzt werden. | m=\left(Q_{\mathrm{R}, \mathrm{e}}+Q_{\mathrm{R}, \mathrm{Tr}}\right) / Q_{\mathrm{T}, \mathrm{aM}} \tag{24} — printed p.54', verification_note='md-verified 2026-09-05 (§7.3.4.2 Gl. (24), printed p.54; duplicate of A1022-23.m (see STAGED)) [VC]', verified_at=now() where id='70092079-5467-4691-a46e-f34c46207414' and verification_status not in ('verified_against_standard','corrected');

-- ######################## EQUATIONS ########################
-- A1022-05 Gl.1 → A_b_a
update public.equations set verification_status='verified_against_standard', verification_quote='Nachweislich (und vollständig) vom betrachteten Entwässerungssystem abgekoppelte Teilflächen bleiben in der Abfluss- und Frachtbilanzierung für den Bezugspunkt außer Acht. Als vollständig abgekoppelt gelten Teilflächen, die im bemessungsrelevanten Regenspektrum der dezentralen Anlagen (Wiederkehrzeiten z. B. 3 a bis 5 a) keinen Abflussbeitrag zum betrachteten Entwässerungssystem liefern. Sie werden der Flächengröße $A_{E, k, b, n a}$ zugerechnet. Die angeschlossene befestigte Fläche $A_{b, a}$ berechnet sich nach GL. (1) entsprechend zu: | A_{\mathrm{b}, \mathrm{a}}=A_{\mathrm{E}, \mathrm{k}, \mathrm{~b}}-A_{\mathrm{E}, \mathrm{k}, \mathrm{~b}, \mathrm{na}} \text { in ha } \tag{1} — printed p.28', verification_note='md-verified 2026-09-05 (§4.2.5 Gl. (1), printed p.28) [VC]', verified_at=now() where id='997a1ee0-0288-4fbd-ab24-3afee90f6cdb' and verification_status <> 'verified_against_standard';
-- A1022-05 Gl.2 → V_R_aM
update public.equations set verification_status='verified_against_standard', verification_quote='$V_{\text {R,am }}$ berechnet sich aus der Jahresniederschlagshöhe $h_{\mathrm{Na}}$ und dem Jahresabflussbeiwert $\psi_{\mathrm{aM}}$ in Bezug auf die angeschlossene befestigte Fläche $A_{\mathrm{b}, \mathrm{a}}$ nach Gl. (2). | V_{\mathrm{R}, \mathrm{aM}}=h_{\mathrm{Na}}(\mathrm{~mm} / \mathrm{a}) \cdot A_{\mathrm{b}, \mathrm{a}}(\mathrm{ha}) \cdot \psi_{\mathrm{aM}}(-) \cdot 10 \quad \text { in m}^{3} / \mathrm{a} \tag{2} — printed p.29', verification_note='md-verified 2026-09-05 (§4.3.3 Gl. (2), printed p.29) [VC]', verified_at=now() where id='c4495497-60aa-479b-99d8-4d9b1ae2ec7e' and verification_status <> 'verified_against_standard';
-- A1022-08 Gl.B.4 → Q_M
update public.equations set verification_status='verified_against_standard', verification_quote='Der Mischwasserabfluss zur Kläranlage $Q_{M}$ ist eine zentrale Einflussgröße auf das Entlastungsverhalten von Mischsystemen und somit auch für die Ermittlung des erforderlichen Gesamtspeichervolumens. Die zahlenmäßige Festlegung von $Q_{M}$ erfolgt grundsätzlich in Abstimmung mit den Bemes-sungs- und Betriebsdaten der Kläranlage. $Q_{\mathrm{M}}$ berechnet sich nach Arbeitsblatt ATV-DVWK-A 198 gemäß GL. (B.4). | Q_{\mathrm{M}}=f_{\mathrm{S}, \mathrm{QM}} \cdot Q_{\mathrm{S}, \mathrm{aM}}+Q_{\mathrm{F}} \quad \text { in l/s } \tag{B.4} — printed p.85', verification_note='md-verified 2026-09-05 (Anh. B.3.2.3.1 Gl. (B.4), printed p.85) [VC]', verified_at=now() where id='5f36c093-d01e-4d4b-a723-9573374f7bc1' and verification_status <> 'verified_against_standard';
-- A1022-08 Gl.B.5 → Q_M
update public.equations set verification_status='verified_against_standard', verification_quote='Für jedes Teileinzugsgebiet können das erforderliche Speichervolumen und der maßgebende Drosselabfluss gesondert ermittelt werden. Die Summe der Mischwasserabflüsse $Q_{M, i}$ der Teilgebiete darf zu keinem Zeitpunkt den Bemessungswert der Kläranlage bei Mischwasserabfluss $\left(Q_{M}\right)$ überschreiten: | \sum Q_{M, i} \leq Q_{M} \quad \text { in l/s } \tag{B.5} — printed p.85', verification_note='md-verified 2026-09-05 (Anh. B.3.2.3.3 Gl. (B.5), printed p.85 — printed as an inequality; the encoded formula carries the relational operator (see STAGED)) [VC]', verified_at=now() where id='44d37420-9559-4b89-a305-e87cf516e488' and verification_status <> 'verified_against_standard';
-- A1022-08 Gl.B.6 → Q_R_Tr
update public.equations set verification_status='verified_against_standard', verification_quote='Liegen keine Messungen vor, ist mit einem Zuschlag von $100 \%$ des maximal stündlichen Schmutzwasserabflusses $Q_{S, h, \text { max }, \text { Tr }}$ zu rechnen (GL. B.6). | Q_{\mathrm{R}, \mathrm{Tr}}=Q_{\mathrm{S}, \mathrm{~h}, \mathrm{max}, \mathrm{Tr}} \quad \text { in } \mathrm{l} / \mathrm{s} \tag{B.6} — printed p.86', verification_note='md-verified 2026-09-05 (Anh. B.3.2.4 Gl. (B.6), printed p.86) [VC]', verified_at=now() where id='fdb39a49-f9d9-47e4-9ac4-5605b8242f7c' and verification_status <> 'verified_against_standard';
-- A1022-10 Gl.3 → B_R_a_AFS63_i
update public.equations set verification_status='verified_against_standard', verification_quote='Für den Stoffabtrag $B_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63, \mathrm{i}}$ der Teilfläche $A_{\mathrm{b}, \mathrm{a}, \mathrm{i}}$ gilt: | B_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63, \mathrm{i}}=A_{\mathrm{b}, \mathrm{a}, \mathrm{i}} \cdot b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63, \mathrm{i}} \quad \text { in } \mathrm{kg} / \mathrm{a} \tag{3} | b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63, \mathrm{i}} \quad \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a}) \quad \text { flächenspezifischer Stoffabtrag AFS63, Teilfläche i } — printed p.34', verification_note='md-verified 2026-09-05 (§5.2.3.2 Gl. (3), printed p.34) [VC]', verified_at=now() where id='a6eae5bc-bc2a-4b75-bb61-77a70220d6cd' and verification_status <> 'verified_against_standard';
-- A1022-10 Gl.4 → B_R_a_AFS63
update public.equations set verification_status='verified_against_standard', verification_quote='Der Stoffabtrag des Gebiets beträgt: | B_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63}=\Sigma B_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63, \mathrm{i}} \quad \text { in kg/a } \tag{4} | B_{\text {R, } \mathrm{a}, \text { AFS63 }} \quad \mathrm{kg} / \mathrm{a} \quad \text { jährlicher Stoffabtrag AFS63 des betrachteten Gebiets } — printed p.34', verification_note='md-verified 2026-09-05 (§5.2.3.2 Gl. (4), printed p.34) [VC]', verified_at=now() where id='ed169cec-be2a-42c0-b6db-71a80e491228' and verification_status <> 'verified_against_standard';
-- A1022-10 Gl.5 → b_R_a_AFS63
update public.equations set verification_status='verified_against_standard', verification_quote='Der resultierende flächenspezifische Stoffabtrag des betrachteten Gebiets ergibt sich zu: | b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63}=B_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63} / \Sigma A_{\mathrm{b}, \mathrm{a}, \mathrm{i}}=B_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63} / A_{\mathrm{b}, \mathrm{a}} \quad \text { in } \mathrm{kg} /(\mathrm{ha} \cdot \mathrm{a}) \tag{5} | b_{\text {R, } \mathrm{a}, \text { AF663 }} \quad \mathrm{kg} /(\text { ha ⋅ } \mathrm{a}) \quad \text { flächenspezifischer Stoffabtrag AFS63 des betrachteten Gebiets } — printed p.34', verification_note='md-verified 2026-09-05 (§5.2.3.2 Gl. (5), printed p.34) [VC]', verified_at=now() where id='7e0416d5-115e-48bd-a747-d97b782f66cd' and verification_status <> 'verified_against_standard';
-- A1022-11 Gl.6 → eta_erf
update public.equations set verification_status='verified_against_standard', verification_quote='Der erforderliche Wirkungsgrad der Behandlungsmaßnahmen ergibt sich nach GL. (6): | \eta_{\text {erf }}=\operatorname{Max}\left(0 ; 1-b_{R, e, z u l, A F S 63} / b_{R, a, A F S 63}\right) & \quad(-) \text { bzw } . \\ \eta_{\text {erf }}=\operatorname{Max}\left(0 ; 1-b_{R, e, z u l, A F 63} / b_{R, a, A F S 63}\right) \cdot 100 & \text { in } \% \tag{6} | $\eta_{\text {erf }}$ & (-) oder $\%$ & erforderlicher Wirkungsgrad der Behandlungsmaßnahme \\ $b_{\mathrm{R}, \mathrm{e}, \mathrm{zu}, \mathrm{AFS} 63}$ & $\mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$ & zulässiger flächenspezifischer Stoffaustrag AFS63 — printed p.34', verification_note='md-verified 2026-09-05 (§5.2.3.2 Gl. (6), printed p.34 — the printed argument separator is „;"; the encoded max(a, b) is the same function) [VC]', verified_at=now() where id='08d98c33-b401-44b3-ae04-d9193150c7d2' and verification_status <> 'verified_against_standard';
-- A1022-12 Gl.7 → B_R_e_AFS63_i
update public.equations set verification_status='verified_against_standard', verification_quote='Der resultierende Stoffaustrag $B_{\text {R,e,AFS63, } \mathrm{i}}$ nach einer Behandlungsanlage ergibt sich bei dezentraler Behandlung für einzelne Teilflächen zu: | B_{R, e, A F S 63, i}=A_{b, a, i} \cdot\left(1-\eta_{i}\right) \cdot b_{R, a, A F S 63, i} \quad \text { in kg/a } \tag{7} | $\eta_{\mathrm{i}}$ (-) Wirksamkeit des Stoffrückhalts der Behandlungsanlage $i$ — printed p.34', verification_note='md-verified 2026-09-05 (§5.2.3.2 Gl. (7), printed p.34) [VC]', verified_at=now() where id='daef07a1-965b-4b4b-b1e4-7ba168a905fc' and verification_status <> 'verified_against_standard';
-- A1022-12 Gl.8 → B_R_e_AFS63
update public.equations set verification_status='verified_against_standard', verification_quote='Für das Gesamtgebiet bei zentraler Behandlung gilt für den resultierenden Stoffaustrag: | B_{\mathrm{R}, \mathrm{e}, \mathrm{AFS} 63}=\left(1-\eta_{\mathrm{ges}}\right) \cdot B_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63} \quad \text { in } \mathrm{kg} / \mathrm{a} \tag{8} | $\eta_{\text {ges }}$ (-) Wirksamkeit des Stoffrückhalts der zentralen Behandlungsanlage — printed p.35', verification_note='md-verified 2026-09-05 (§5.2.3.2 Gl. (8), printed p.35) [VC]', verified_at=now() where id='ecd555eb-d4a2-42b3-8f3a-5349ae367302' and verification_status <> 'verified_against_standard';
-- A1022-13 Gl.B.1 → Q_R_krit
update public.equations set verification_status='verified_against_standard', verification_quote='Der kritische Regenwasserabfluss $Q_{\mathrm{R}, \mathrm{krit}}$ bezeichnet entsprechend B.1.2 die Größe des Regenwasserabflusses, der einer Behandlung zugeführt wird. Er berechnet sich über die gewählte kritische Regenspende $r_{\text {krit }}$ und die angeschlossene befestigte Fläche $A_{\mathrm{b}, \mathrm{a}}$ des direkten Einzugsgebiets der Behandlungsanlage: | Q_{\mathrm{R}, \text { krit }}=r_{\text {krit }} \cdot A_{\mathrm{b}, \mathrm{a}} \cdot f_{\mathrm{D}} \quad \text { in } \mathrm{l} / \mathrm{s} \tag{B.1} — printed p.80', verification_note='md-verified 2026-09-05 (Anh. B.1.3 Gl. (B.1), printed p.80 — the f_D factor is the Aug-2022 correction) [VC]', verified_at=now() where id='acd00262-4e8f-48db-acab-e544450601a2' and verification_status <> 'verified_against_standard';
-- A1022-14 Gl.B.2 → Q_Bem_Tr
update public.equations set verification_status='verified_against_standard', verification_quote='Der Bemessungszufluss $Q_{\text {Bem, Tr }}$ bestimmt die maximale hydraulische Belastung der Behandlungsanlage im Trennverfahren und damit den Anteil des der Behandlung zugeführten Regenwasserabflussvolumens. Er errechnet sich abhängig von der gewählten kritischen Regenspende $r_{\text {krit }}$ als Summe des kritischen Regenabflusses $Q_{\mathrm{R}, \text { krit }}$ und des maßgebenden Fremdwasserabflusses $Q_{\mathrm{F}}$ zu: | Q_{\mathrm{Bem}, \mathrm{Tr}}=Q_{\mathrm{R}, \text { krit }}+Q_{\mathrm{F}} \quad \text { in } \mathrm{l} / \mathrm{s} \tag{B.2} — printed p.82', verification_note='md-verified 2026-09-05 (Anh. B.2.1 Gl. (B.2), printed p.82) [VC]', verified_at=now() where id='d0256603-30ed-4e04-8bb0-a141e0548c26' and verification_status <> 'verified_against_standard';
-- A1022-15 Gl.9 → q_A_b
update public.equations set verification_status='verified_against_standard', verification_quote='Für bestehende Anlagen, die mit davon abweichendem $r_{\text {krit }}$ bemessen wurden, kann der maßgebende Gesamtwirkungsgrad näherungsweise über die Oberflächenbeschickung $q_{\mathrm{A}, \mathrm{b}}$, abgeleitet aus der bei der Bemessungsregenspende auftretenden maximalen Oberflächenbeschickung $q_{\mathrm{A}, \max }$ nach GL. (9), abgeschätzt werden. | q_{\mathrm{A}, \mathrm{~b}}=q_{\mathrm{A}, \max } \cdot 15 / r_{\text {krit }} \quad \text { in } \mathrm{m} / \mathrm{h} \tag{9} | q_{\mathrm{A}, \mathrm{~b}} \quad \mathrm{~m} / \mathrm{h} \quad \text { maßgebende Oberflächenbeschickung im Bestand } — printed p.41', verification_note='md-verified 2026-09-05 (§6.2.2 Gl. (9), printed p.41) [VC]', verified_at=now() where id='ee790735-7db9-488d-9082-b07343521138' and verification_status <> 'verified_against_standard';
-- A1022-15 Gl.B.3 → q_A_Bem
update public.equations set verification_status='verified_against_standard', verification_quote='Die Oberflächenbeschickung $q_{\mathrm{A}}$ bestimmt maßgeblich den erreichbaren Grad des Feststoffrückhalts in Sedimentationsanlagen. Der Bemessungswert $q_{\mathrm{A}, \mathrm{Bem}}$ der Oberflächenbeschickung ist die hydraulische Beschickung beim Bemessungszufluss $Q_{\text {Bem, Tr. }}$ Er berechnet sich nach GI. (B.3) zu: | q_{\mathrm{A}, \text { Bem }}=3,6 \cdot Q_{\text {Bem }, \mathrm{Tr}} / A_{\text {sed }} \text { in } \mathrm{m} / \mathrm{h} \tag{B.3} | $A_{\text {sed }} \quad$ in $\mathrm{m}^{2} \quad$ sedimentationswirksame Oberfläche der Sedimentationsanlage — printed p.82', verification_note='md-verified 2026-09-05 (Anh. B.2.2 Gl. (B.3), printed p.82) [VC]', verified_at=now() where id='5341b82e-0ac8-4fa9-8d51-80bbbf90cde8' and verification_status <> 'verified_against_standard';
-- RESIDUE A1022-17 Gl.REG-Bild4 (f24d3d57-1d4f-4bf4-8a2b-30978d188535): the guideline prints no equation for this relation — Bild 4 is a graph. Not verified here; see STAGED.
-- A1022-18 Gl.10 → A_RKB
update public.equations set verification_status='verified_against_standard', verification_quote='Die erforderliche sedimentationswirksame Oberfläche leitet sich aus dem Bemessungszufluss und der nach Bild 4 erforderlichen Oberflächenbeschickung $q_{\mathrm{A}, \mathrm{Bem}} \mathrm{ab}$, mit der der maßgebende Gesamtwirkungsgrad $\eta_{\text {ges }}$ erzielt wird. Die Beckenoberfläche $A_{\text {RKB }}$ berechnet sich nach GL. (10) | A_{\text {RKB }}=3,6 \cdot Q_{\text {Bem }, \text { Tr }} / q_{\text {A,Bem }} \quad \text { in } \mathrm{m}^{2} \tag{10} — printed p.42', verification_note='md-verified 2026-09-05 (§6.2.3 Gl. (10), printed p.42) [VC]', verified_at=now() where id='bd2ca141-44d0-4541-be76-bf2170e92f35' and verification_status <> 'verified_against_standard';
-- A1022-18 Gl.11 → V_RKB
update public.equations set verification_status='verified_against_standard', verification_quote='Hinweise zur konstruktiven Gestaltung von Regenklärbecken enthält das Arbeitsblatt DWA-A 166. In Ergänzung dazu wird für Regenklärbecken aus hydraulisch-konstruktiven Gründen eine Mindesttiefe von 2 m empfohlen. Damit resultiert das erforderliche Speichervolumen nach GL. (11): | V_{\text {RKB }}=A_{\text {RKB }} \cdot h_{\text {RKB }} \quad \text { in m }{ }^{3} \tag{11} — printed p.42', verification_note='md-verified 2026-09-05 (§6.2.4 Gl. (11), printed p.42) [VC]', verified_at=now() where id='ff6456ed-db2f-4399-9183-d8b9d47e55c9' and verification_status <> 'verified_against_standard';
-- A1022-18 Gl.12 → A_eff
update public.equations set verification_status='verified_against_standard', verification_quote='Für Schrägklärer ist die sedimentationswirksame Oberfläche $A_{\text {eff }}$ der Einbauten (.,Sedimentationskör- per") maßgebend. Die erforderliche Oberfläche $A_{\text {eff }}$ berechnet sich nach GL. (12): | A_{\mathrm{eff}}=3,6 \cdot Q_{\mathrm{Bem}, \mathrm{Tr}} / q_{\mathrm{A}, \max } \quad \text { in } \mathrm{m}^{2} \tag{12} | $A_{\text {eff }} \quad \mathrm{m}^{2} \quad$ sedimentationswirksame Oberfläche des Sedimentationskörpers — printed p.43', verification_note='md-verified 2026-09-05 (§6.3 Gl. (12), printed p.43) [VC]', verified_at=now() where id='e79ac053-281c-450b-a11e-c3eadaafcbae' and verification_status <> 'verified_against_standard';
-- A1022-19 Gl.B.7 → Q_R_Dr
update public.equations set verification_status='verified_against_standard', verification_quote='In Mischsystemen errechnet sich der für die Bemessung maßgebende Regenabfluss im Drosselabfluss zur Kläranlage $Q_{R, D r}$ aus der Differenz zwischen dem Mischwasserabfluss $Q_{M}$, dem Trockenwetterabfluss $Q_{\text {T,am }}$ und dem Regenabfluss aus Trenngebieten $Q_{\text {R, Tr }}$ entsprechend GL. (B.7): | Q_{R, D r}=Q_{M}-Q_{T, a M}-Q_{R, T r} \quad \text { in l/s } \tag{B.7} — printed p.87', verification_note='md-verified 2026-09-05 (Anh. B.3.3.1 Gl. (B.7), printed p.87) [VC]', verified_at=now() where id='929c3944-03c9-4c42-98ee-3a824a7b27c3' and verification_status <> 'verified_against_standard';
-- A1022-19 Gl.B.8 → q_R_Dr
update public.equations set verification_status='verified_against_standard', verification_quote='Abweichend von Arbeitsblatt ATV-DVWK-A 198:2003 ist die Regenabflussspende $q_{\text {R,Dr }}$ im Kontext des Berechnungsverfahrens zum erforderlichen Gesamtspeichervolumen definiert als Quotient aus dem Regenabfluss im Drosselabfluss $Q_{R, D r}$ und der angeschlossenen befestigten Fläche $A_{b, a}$ (GL. B.8). | q_{\mathrm{R}, \mathrm{Dr}}=Q_{\mathrm{R}, \mathrm{Dr}} / A_{\mathrm{b}, \mathrm{a}} \quad \text { in l/(s•ha) } \tag{B.8} — printed p.87', verification_note='md-verified 2026-09-05 (Anh. B.3.3.2 Gl. (B.8), printed p.87) [VC]', verified_at=now() where id='c86641c2-c5bc-407e-9dba-969169250768' and verification_status <> 'verified_against_standard';
-- A1022-20 Gl.B.9 → q_T_aM
update public.equations set verification_status='verified_against_standard', verification_quote='Die auf das Jahresmittel bezogene Trockenwetterabflussspende $q_{\mathrm{T}, \mathrm{aM}}$ errechnet sich nach GL. (B.9): | q_{\mathrm{T}, \mathrm{aM}}=Q_{\mathrm{T}, \mathrm{aM}} / A_{\mathrm{b}, \mathrm{a}} \quad \text { in l/(s•ha) } \tag{B.9} — printed p.87', verification_note='md-verified 2026-09-05 (Anh. B.3.3.3 Gl. (B.9), printed p.87) [VC]', verified_at=now() where id='42cbd2b0-dab8-4e39-b7c9-ee05b269a605' and verification_status <> 'verified_against_standard';
-- A1022-21 Gl.B.10 → a_f
update public.equations set verification_status='verified_against_standard', verification_quote='Der Faktor $a_{\mathrm{f}}$ zur Berücksichtigung der Abminderung von Abflussspitzen, hier des empirischen Wertes $Q_{\mathrm{R}, \mathrm{e}}$ nach GL. (B.12), berechnet sich nach GL. (B.10): | a_{\mathrm{f}}=0,50+50 /\left(t_{\mathrm{f}}+100\right) & \text { für } t_{\mathrm{f}} \leq 30 \mathrm{~min} \tag{B.10}\\ a_{\mathrm{f}}=0,885 & \text { für } t_{\mathrm{f}}>30 \mathrm{~min} — printed p.87', verification_note='md-verified 2026-09-05 (Anh. B.3.3.4 Gl. (B.10), printed p.87 — printed as a two-branch case on t_f ≤ / > 30 min; the encoded max() reproduces both branches) [VC]', verified_at=now() where id='1cd06fe2-0b67-447b-895c-0db16528edd1' and verification_status <> 'verified_against_standard';
-- A1022-21 Gl.T6.a_f → a_f
update public.equations set verification_status='verified_against_standard', verification_quote='\hline 23 & Fließzeitabminderung & $a_{\mathrm{f}}=0,5+50 /\left(t_{\mathrm{f}}+100\right) ;>=0,885$ & $a_{\mathrm{f}}$ & 0,885 & - \\ | Der Faktor $a_{\mathrm{f}}$ zur Berücksichtigung der Abminderung von Abflussspitzen, hier des empirischen Wertes $Q_{\mathrm{R}, \mathrm{e}}$ nach GL. (B.12), berechnet sich nach GL. (B.10): | a_{\mathrm{f}}=0,50+50 /\left(t_{\mathrm{f}}+100\right) & \text { für } t_{\mathrm{f}} \leq 30 \mathrm{~min} \tag{B.10}\\ a_{\mathrm{f}}=0,885 & \text { für } t_{\mathrm{f}}>30 \mathrm{~min} — printed p.51, p.87', verification_note='md-verified 2026-09-05 (Tab. 6 Zeile 23 p.51 = Anh. B.3.3.4 Gl. (B.10) p.87 — duplicate of Gl.B.10 (see STAGED)) [VC]', verified_at=now() where id='6e412ae9-f9e5-462b-9cfb-8b5bdc854d3b' and verification_status <> 'verified_against_standard';
-- A1022-22 Gl.B.11 → Q_R_e
update public.equations set verification_status='verified_against_standard', verification_quote='Dividiert man das Jahresentlastungsvolumen eines Überlaufbauwerks ( $V_{\text {e, Mwü }}$ ) durch die zugehörige Gesamtdauer der Entlastungsereignisse ( $D_{\mathrm{e}}$ ), erhält man als Rechenwert einen mittleren Entlastungsabfluss aus dem Bauwerk. Gleichzeitig fließt durch die Drossel während des Überlaufvorgangs der Regenanteil $Q_{R, D r} \mathrm{ab}$. Beide Abflüsse zusammen ergeben den mittleren Regenwasserabfluss $Q_{R, e}$ während aller Entlastungsereignisse im Laufe eines Jahres nach GL. (B.11): | Q_{R, e}=V_{e, \mathrm{MWÜ}} /\left(D_{e} \cdot 3,6\right)+Q_{R, \mathrm{Dr}} \quad \text { in l/s } \tag{B.11} — printed p.88', verification_note='md-verified 2026-09-05 (Anh. B.3.3.5 Gl. (B.11), printed p.88) [VC]', verified_at=now() where id='aa0ed5ff-3b65-440b-8922-80c78e4dc84a' and verification_status <> 'verified_against_standard';
-- A1022-22 Gl.B.12 → Q_R_e
update public.equations set verification_status='verified_against_standard', verification_quote='Für Regenüberlaufbecken kann der mittlere Regenwasserabfluss $Q_{R, e}$ während der Entlastungen angenähert durch die empirische Gleichung (B.12) errechnet werden, solange die Regenabflussspende $q_{\mathrm{R}, \mathrm{Dr}}$ kleiner ist als $2 \mathrm{l} /(\mathrm{s} \cdot \mathrm{ha})$ : | Q_{R, e}=a_{f} \cdot\left(3,0 \cdot A_{b, a} \cdot f_{D}+3,2 \cdot Q_{R, D r}\right) \quad \text { in } L / s \tag{B.12} — printed p.88', verification_note='md-verified 2026-09-05 (Anh. B.3.3.5 Gl. (B.12), printed p.88 — valid only while q_R,Dr < 2 l/(s·ha); that guard is not encoded (see STAGED)) [VC]', verified_at=now() where id='33301fd3-1cd7-4a09-980a-55cbcb9b8ae6' and verification_status <> 'verified_against_standard';
-- A1022-23 Gl.B.13 → m
update public.equations set verification_status='verified_against_standard', verification_quote='Das mittlere Mischverhältnis $m$ zwischen Regenwasser- und Trockenwetterabfluss während aller Entlastungsereignisse ergibt sich nach GI. (B.13) als Verhältnis aus dem mittleren Regenwasserabfluss während sämtlicher Entlastungsereignisse eines Jahres $Q_{R, e}$, zuzüglich dem Regenwasserabfluss aus Trenngebieten $Q_{\mathrm{R}, \mathrm{Tr}}$ und dem gleichzeitig zufließenden mittleren Trockenwetterabfluss $Q_{\mathrm{T}, \mathrm{aM}}$. | m=\left(Q_{\mathrm{R}, \mathrm{e}}+Q_{\mathrm{R}, \mathrm{Tr}}\right) / Q_{\mathrm{T}, \mathrm{aM}} \tag{B.13} — printed p.88', verification_note='md-verified 2026-09-05 (Anh. B.3.3.6 Gl. (B.13), printed p.88) [VC]', verified_at=now() where id='88c45a6c-2601-419c-b713-f4a799d7afea' and verification_status <> 'verified_against_standard';
-- A1022-24 Gl.B.15a → a_c_CSB
update public.equations set verification_status='verified_against_standard', verification_quote='Bei CSB-Konzentrationen im Trockenwetterabfluss $C_{\mathrm{T}, \mathrm{am}, \mathrm{CSB}}$ über $600 \mathrm{mg} / \mathrm{l}$, wird dies durch den Einflussfaktor $a_{\mathrm{c}, \mathrm{CSB}}$ als „Starkverschmutzungszuschlag“ entsprechend GL. (B.15) bei der Berechnung der Bemessungskonzentration $C_{\mathrm{b}, \text { CSB }}$ berücksichtigt: | a_{\mathrm{c}, \mathrm{CSB}}=1 \quad \text { für } \quad C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}} \leq 600 \mathrm{mg} / \mathrm{l} \tag{B.15a} | a_{\mathrm{c}, \mathrm{CSB}}=C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}} / 600 \quad \text { für } \quad C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}>600 \mathrm{mg} / \mathrm{l} \tag{B.15b} — printed p.88', verification_note='md-verified 2026-09-05 (Anh. B.3.3.8 Gl. (B.15a), printed p.88 — branch a of a two-branch case; encoded merged as max(1, C/600)) [VC]', verified_at=now() where id='739e1f02-ad16-4410-80d8-dadf7173451a' and verification_status <> 'verified_against_standard';
-- A1022-24 Gl.B.15b → a_c_CSB
update public.equations set verification_status='verified_against_standard', verification_quote='Bei CSB-Konzentrationen im Trockenwetterabfluss $C_{\mathrm{T}, \mathrm{am}, \mathrm{CSB}}$ über $600 \mathrm{mg} / \mathrm{l}$, wird dies durch den Einflussfaktor $a_{\mathrm{c}, \mathrm{CSB}}$ als „Starkverschmutzungszuschlag“ entsprechend GL. (B.15) bei der Berechnung der Bemessungskonzentration $C_{\mathrm{b}, \text { CSB }}$ berücksichtigt: | a_{\mathrm{c}, \mathrm{CSB}}=1 \quad \text { für } \quad C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}} \leq 600 \mathrm{mg} / \mathrm{l} \tag{B.15a} | a_{\mathrm{c}, \mathrm{CSB}}=C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}} / 600 \quad \text { für } \quad C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}>600 \mathrm{mg} / \mathrm{l} \tag{B.15b} — printed p.88', verification_note='md-verified 2026-09-05 (Anh. B.3.3.8 Gl. (B.15b), printed p.88 — branch b; identical encoded formula to Gl.B.15a (see STAGED)) [VC]', verified_at=now() where id='135015bc-ebf9-4818-844a-93dd9a2b853c' and verification_status <> 'verified_against_standard';
-- A1022-24 Gl.B.16 → a_h
update public.equations set verification_status='verified_against_standard', verification_quote='Dieser Einfluss wird in der Bemessungskonzentration $C_{\mathrm{b}, \text { CSB }}$ über den Einflusswert $a_{\mathrm{h}}$ berücksichtigt. Der Einflusswert $a_{\mathrm{h}}$ ergibt sich aus GL. (B.16). | a_{\mathrm{h}}=h_{\mathrm{Na}} / 800-1 & \text { für } & 600 \leq h_{\mathrm{Na}} \leq 1.000 \mathrm{~mm} \tag{B.16}\\ a_{\mathrm{h}}=-0,25 & \text { für } & h_{\mathrm{Na}}<600 \mathrm{~mm} \\ a_{\mathrm{h}}=+0,25 & \text { für } & h_{\mathrm{Na}}>1.000 \mathrm{~mm} — printed p.89', verification_note='md-verified 2026-09-05 (Anh. B.3.3.9 Gl. (B.16), printed p.89 — the printed range is 600 ≤ h_Na ≤ 1.000 mm with clamps at ±0,25) [VC]', verified_at=now() where id='89c13422-4fe9-423b-92a7-b59a00b9345d' and verification_status <> 'verified_against_standard';
-- A1022-24 Gl.B.17 → d_I
update public.equations set verification_status='verified_against_standard', verification_quote='Angesichts der allgemeinen Verfügbarkeit detaillierter Kanalnetzdaten wird empfohlen, den Einflusswert der Kanalablagerungen $a_{\mathrm{a}}$ direkt über die Kennwerte der Kanäle im Einzugsgebiet zu ermitteln. Dazu wird $d \cdot I$ als längengewichtetes Produkt aus Durchmesser $d$ (Breite bei Nichtkreisprofilen) und Sohlengefälle $I_{\mathrm{S}}$ der einzelnen Kanäle ermittelt: | $d \cdot I=\Sigma$ (Durchmesser • Gefälle • Länge) / Gesamtlänge in m $d \cdot I \quad=\sum\left(d_{\mathrm{i}} \cdot I_{\mathrm{s}, \mathrm{i}} \cdot l_{\mathrm{i}}\right) / \sum l_{\mathrm{i}} \quad$ in m — printed p.89', verification_note='md-verified 2026-09-05 (Anh. B.3.3.10 Gl. (B.17), printed p.89 — the md prints this inside a code block without a visible tag number) [VC]', verified_at=now() where id='c2ef6396-4394-4be5-9bd7-456b518deea8' and verification_status <> 'verified_against_standard';
-- A1022-24 Gl.B.18 → d_I
update public.equations set verification_status='verified_against_standard', verification_quote='Stehen die detaillierten Kanalnetzdaten nicht zur Verfügung, kann die Größe $d \cdot I$ näherungsweise über die flächengewichtete, mittlere Geländeneigungsklasse $N G_{\mathrm{m}}$ abgeschätzt werden. | d \cdot I=0,001 \cdot\left(1+2\left(N G_{\mathrm{m}}-1\right)\right) \quad \text { in } \mathrm{m} \tag{B.18} — printed p.89', verification_note='md-verified 2026-09-05 (Anh. B.3.3.10 Gl. (B.18), printed p.89) [VC]', verified_at=now() where id='d5a0f906-917e-4038-9ada-1ed13005239a' and verification_status <> 'verified_against_standard';
-- A1022-24 Gl.B.19 → x_a
update public.equations set verification_status='verified_against_standard', verification_quote='Der Einflusswert $a_{\mathrm{a}}$ berechnet sich über die Größe $d \cdot I$ und die Zwischenwerte $x_{\mathrm{a}}$ und $\tau$ wie folgt: | & x_{\mathrm{a}}=24 \cdot Q_{\mathrm{T}, \mathrm{aM}} / Q_{\mathrm{T}, \mathrm{~h}, \max } \tag{B.19}\\ & \tau=430 \cdot\left(q_{\mathrm{T}, \mathrm{aM}} / f_{\mathrm{D}}\right)^{0,45} \cdot(d \cdot I) \tag{B.20}\\ & a_{\mathrm{a}}=\left(24 / x_{\mathrm{a}}\right)^{2} \cdot(2-\tau) / 10 ; a_{\mathrm{a}} \geq 0 \tag{B.21} — printed p.89', verification_note='md-verified 2026-09-05 (Anh. B.3.3.10 Gl. (B.19), printed p.89) [VC]', verified_at=now() where id='1c3f10bd-01f7-4f31-b79a-3094ce76a3dd' and verification_status <> 'verified_against_standard';
