-- A1022-24 Gl.B.21 → a_a
update public.equations set verification_status='verified_against_standard', verification_quote='Der Einflusswert $a_{\mathrm{a}}$ berechnet sich über die Größe $d \cdot I$ und die Zwischenwerte $x_{\mathrm{a}}$ und $\tau$ wie folgt: | & x_{\mathrm{a}}=24 \cdot Q_{\mathrm{T}, \mathrm{aM}} / Q_{\mathrm{T}, \mathrm{~h}, \max } \tag{B.19}\\ & \tau=430 \cdot\left(q_{\mathrm{T}, \mathrm{aM}} / f_{\mathrm{D}}\right)^{0,45} \cdot(d \cdot I) \tag{B.20}\\ & a_{\mathrm{a}}=\left(24 / x_{\mathrm{a}}\right)^{2} \cdot(2-\tau) / 10 ; a_{\mathrm{a}} \geq 0 \tag{B.21} — printed p.89', verification_note='md-verified 2026-09-05 (Anh. B.3.3.10 Gl. (B.21), printed p.89 — the printed „a_a ≥ 0" guard is encoded as max(0, …)) [VC]', verified_at=now() where id='51714be6-c070-42f2-8c0f-a8bec98b32d4' and verification_status <> 'verified_against_standard';
-- A1022-25 Gl.B.14 → C_b_CSB
update public.equations set verification_status='verified_against_standard', verification_quote='Der Konzentrationswert $C_{\mathrm{b}, \text { CSB }}$ berücksichtigt nach einem empirischen Ansatz entsprechend GI. (B.14) den Einfluss der projektbezogenen Kenngrößen Jahresniederschlagshöhe $h_{\mathrm{Na}}$ lim Wertebereich $600 \mathrm{~mm} / \mathrm{a} \leq h_{\mathrm{Na}} \leq 1.200 \mathrm{~mm} / \mathrm{a}$ ) und der CSB-Konzentration im Trockenwetterabfluss (für $C_{\mathrm{T}, \mathrm{am}, \mathrm{CSB}}> 600 \mathrm{mg} / \mathrm{ll}$ sowie der Kanalablagerungen auf das Entlastungsverhalten: | C_{\mathrm{b}, \text { CSB }}=600 \cdot\left(a_{\mathrm{c}, \text { CSB }}+a_{\mathrm{h}}+a_{\mathrm{a}}\right) \quad \text { in } \mathrm{mg} / \mathrm{l} \tag{B.14} — printed p.88', verification_note='md-verified 2026-09-05 (Anh. B.3.3.7 Gl. (B.14), printed p.88) [VC]', verified_at=now() where id='c77b5384-345a-49d7-ab3e-41a05235f35c' and verification_status <> 'verified_against_standard';
-- A1022-26 Gl.21a → a_R_AFS63
update public.equations set verification_status='verified_against_standard', verification_quote='Der Anpassungswert $a_{\mathrm{R}, \mathrm{AFS} 63}$ berechnet sich nach GI. (21), begrenzt auf maximal 1,20: | a_{R, A F S 63}=1,0 & \text { für } & b_{R, a, A F S 63} \leq 478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a}) \\ a_{R, A F S 63}=\operatorname{Min}\left(b_{R, a, A F S 63} / 478 ; 1,20\right) & \text { für } & b_{R, a, A F S 63}>478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a}) \tag{21b} — printed p.49', verification_note='md-verified 2026-09-05 (§7.3.2.2 Gl. (21a), printed p.49) [VC]', verified_at=now() where id='9a210010-2290-49f6-80e7-956680292ecb' and verification_status <> 'verified_against_standard';
-- A1022-26 Gl.21b → a_R_AFS63
update public.equations set verification_status='verified_against_standard', verification_quote='Der Anpassungswert $a_{\mathrm{R}, \mathrm{AFS} 63}$ berechnet sich nach GI. (21), begrenzt auf maximal 1,20: | a_{R, A F S 63}=1,0 & \text { für } & b_{R, a, A F S 63} \leq 478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a}) \\ a_{R, A F S 63}=\operatorname{Min}\left(b_{R, a, A F S 63} / 478 ; 1,20\right) & \text { für } & b_{R, a, A F S 63}>478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a}) \tag{21b} — printed p.49', verification_note='md-verified 2026-09-05 (§7.3.2.2 Gl. (21b), printed p.49 — the printed Min argument separator is „;"; the encoded min(a, b) is the same function) [VC]', verified_at=now() where id='53a5778f-0083-4743-95d0-93e681711b5f' and verification_status <> 'verified_against_standard';
-- A1022-26 Gl.B.22 → b_R_a_AFS63
update public.equations set verification_status='verified_against_standard', verification_quote='Der flächenspezifische Stoffabtrag $b_{\text {R,a,AFS63 }}$ errechnet sich projektbezogen aus dem Ergebnis der für das Einzugsgebiet durchgeführten Flächenkategorisierung mit den Rechenwerten nach 5.2.2.3 (Tabelle 4) und den Flächenanteilen $p \mathrm{I}$ bis $p \mathrm{III}$ in \% nach GL. (B.22): | b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63}=(p \mathrm{I} \cdot 280+p \mathrm{II} \cdot 530+p \mathrm{III} \cdot 760) / 100 \quad \text { in } \mathrm{kg} /(\mathrm{ha} \cdot \mathrm{a}) \tag{B.22} — printed p.90', verification_note='md-verified 2026-09-05 (Anh. B.3.3.11 Gl. (B.22), printed p.90 — this is the Aug-2022 corrected numbering (was Gl. B.23)) [VC]', verified_at=now() where id='3fe9e932-5352-41cb-8212-ca5d7fcd6d8b' and verification_status <> 'verified_against_standard';
-- A1022-26 Gl.B.23a → a_R_AFS63
update public.equations set verification_status='verified_against_standard', verification_quote='Bezugsbasis hierfür ist der Rechenwert des flächenspezifischen Stoffabtrags $b_{R, a, A F S 63}$, der für eine typische Relation der Flächenanteile der Belastungskategorien I bis III mit $478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$ abgeleitet wurde (siehe 5.2.2.3). Resultieren entsprechend B.3.3.11 für $b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63}$ höhere Werte, wird dies über den Einflusswert $a_{\mathrm{R}, \mathrm{AFS} 63}$ nach Gl. (B.23a/b) und die darüber angepasste Regenwasserkonzentration $C_{\mathrm{R}, \mathrm{a}}$ (B.3.3.13) berücksichtigt: | a_{R, A F S 63}=1,0 & \text { für } b_{R, a, A F S 63} \leq 478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a}) \\ a_{R, A F S 63}=\operatorname{Min}\left(b_{R, a, A F S 63} / 478 ; 1,20\right) & \text { für } b_{R, a, A F S 63}>478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a}) — printed p.90', verification_note='md-verified 2026-09-05 (Anh. B.3.3.12 Gl. (B.23a), printed p.90 — same equation as Gl.21a (see STAGED)) [VC]', verified_at=now() where id='517badbe-f603-483f-9d94-17b81d398834' and verification_status <> 'verified_against_standard';
-- A1022-26 Gl.B.23b → a_R_AFS63
update public.equations set verification_status='verified_against_standard', verification_quote='Bezugsbasis hierfür ist der Rechenwert des flächenspezifischen Stoffabtrags $b_{R, a, A F S 63}$, der für eine typische Relation der Flächenanteile der Belastungskategorien I bis III mit $478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$ abgeleitet wurde (siehe 5.2.2.3). Resultieren entsprechend B.3.3.11 für $b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63}$ höhere Werte, wird dies über den Einflusswert $a_{\mathrm{R}, \mathrm{AFS} 63}$ nach Gl. (B.23a/b) und die darüber angepasste Regenwasserkonzentration $C_{\mathrm{R}, \mathrm{a}}$ (B.3.3.13) berücksichtigt: | a_{R, A F S 63}=1,0 & \text { für } b_{R, a, A F S 63} \leq 478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a}) \\ a_{R, A F S 63}=\operatorname{Min}\left(b_{R, a, A F S 63} / 478 ; 1,20\right) & \text { für } b_{R, a, A F S 63}>478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a}) | Der Einflusswert $a_{\mathrm{R}, \mathrm{AFS} 63}$ wird auf einen Maximalwert von 1,20 begrenzt. Dieser Wert wird bei einer flächenspezifischen Abtragsfracht $b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63}$ von ca. $570 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$ erreicht. — printed p.90', verification_note='md-verified 2026-09-05 (Anh. B.3.3.12 Gl. (B.23b), printed p.90 — same equation as Gl.21b (see STAGED)) [VC]', verified_at=now() where id='0cabf252-a613-4295-835b-3f005caa4dc1' and verification_status <> 'verified_against_standard';
-- A1022-27 Gl.19 → C_e_CSB
update public.equations set verification_status='verified_against_standard', verification_quote='Die Entlastungskonzentration $C_{e, C S B}$ errechnet sich allgemein über das mittlere Mischverhältnis, die Konzentration im Regenwasserabfluss $C_{R, C S B}$ und die Bemessungskonzentration $C_{b, C S B}$ (siehe Anhang B, B.3.3.7) nach GL. (19). | C_{\mathrm{e}, \text { CSB }}=\left(C_{\mathrm{R}, \text { CSB }} \cdot m+C_{\mathrm{b}, \text { CSB }}\right) /(m+1) \tag{19} — printed p.49', verification_note='md-verified 2026-09-05 (§7.3.2.2 Gl. (19), printed p.49) [VC]', verified_at=now() where id='7d065f24-3485-4cd3-bc56-a94d82fc5a03' and verification_status <> 'verified_against_standard';
-- A1022-27 Gl.20 → C_e_CSB
update public.equations set verification_status='verified_against_standard', verification_quote='Überschreitet der entsprechend 5.2.2.3 für das Gesamteinzugsgebiet resultierende flächenspezifische Stoffabtrag $b_{\mathrm{R}, \mathrm{a}, \mathrm{AFS} 63}$ den abgeleiteten „Bezugswert" von $478 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$, erfolgt eine modifizierte Berechnung der mittleren Entlastungskonzentration $C_{\mathrm{e}, \mathrm{CSB}}$ nach GI. (20): | C_{\mathrm{e}, \mathrm{CSB}}=\left(C_{\mathrm{R}, \mathrm{CSB}} \cdot a_{\mathrm{R}, \mathrm{AFS} 63} \cdot m+C_{\mathrm{b}, \mathrm{CSB}}\right) /(m+1) — printed p.49', verification_note='md-verified 2026-09-05 (§7.3.2.2 Gl. (20), printed p.49) [VC]', verified_at=now() where id='316f8622-ffef-47a7-829c-909dba3af623' and verification_status <> 'verified_against_standard';
-- A1022-27 Gl.B.24 → C_e_CSB
update public.equations set verification_status='verified_against_standard', verification_quote='Die Mischrechnung zur Bestimmung der mittleren Entlastungskonzentration $C_{\mathrm{e}, \mathrm{CSB}}$ im Überlaufvolumen erfolgt mit der Bemessungskonzentration $C_{b, \text { CSB }}$ in Bezug auf den Trockenwetterabfluss, die mittlere Verschmutzung des Regenwasserabflusses $C_{\text {R,CSB }}$, den Einflusswert $a_{\text {R,AFS63 }}$ und das mittlere Mischverhältnis m nach GL. (B.24): | C_{\mathrm{e}, \mathrm{CSB}}=\left(C_{\mathrm{R}, \mathrm{CSB}} \cdot a_{\mathrm{R}, \mathrm{AFS} 63} \cdot m+C_{\mathrm{b}, \mathrm{CSB}}\right) /(m+1) \quad \text { in } \mathrm{mg} / \mathrm{l} \tag{B.24} — printed p.90', verification_note='md-verified 2026-09-05 (Anh. B.3.3.13 Gl. (B.24), printed p.90 — identical to Gl. (20) p.49 and encoded twice on the same worksheet (see STAGED)) [VC]', verified_at=now() where id='adb9665b-6c15-4e3f-aa7f-923355af3832' and verification_status <> 'verified_against_standard';
-- A1022-28 Gl.13 → e_0
update public.equations set verification_status='verified_against_standard', verification_quote='Die Entlastungsrate $e_{0}$ ist als volumenbezogene Größe über Gl. (13) definiert als Quotient des Jahresentlastungsvolumens an Mischwasserüberläufen ( $V_{e, \text { MWü }}$ ) und des Jahresregenwasserabflussvolumens ( $V_{\text {R,aM }}$ ) in Prozent. | e_{0}=V_{\mathrm{e}, \mathrm{MWU}} / V_{\mathrm{R}, \mathrm{aM}} \cdot 100 \text { in \% } \tag{13} — printed p.48', verification_note='md-verified 2026-09-05 (§7.3.2.2 Gl. (13), printed p.48) [VC]', verified_at=now() where id='a1f91610-47b4-44e3-938e-5249fd446133' and verification_status <> 'verified_against_standard';
-- A1022-28 Gl.14 → B_R_e
update public.equations set verification_status='verified_against_standard', verification_quote='Sie erlaubt die Bilanzierung des jährlichen Stoffaustrags durch Mischwasserüberläufe und den Regenwasseranteil im Kläranlagenablauf in Verbindung mit der mittleren Entlastungskonzentration $C_{\mathrm{e}}$ und den Bezug auf den zulässigen Stoffaustrag gemäß GI. (14): | B_{R, e}=\left(V_{R, a M} \cdot e_{0} \cdot C_{e}+V_{R, a M} \cdot\left(100-e_{0}\right) \cdot C_{K A}\right) / 100 \leq B_{R, e, z u l} \quad \text { in } \mathrm{kg} / \mathrm{a} \tag{14} | \hline $B_{\mathrm{R}, \mathrm{e}}$ & kg/a & resultierender Stoffaustrag durch Regenwasserabflüsse \\ \hline $B_{\text {R, } \mathrm{e,zul}}$ & kg/a & zulässiger jährlicher Stoffaustrag infolge von Regenwasserabflüssen, allgemein \\ \hline C $_{\text {e }}$ & $\mathrm{kg} / \mathrm{m}^{3}$ & mittlere Entlastungskonzentration \\ \hline $C_{\text {KA }}$ & $\mathrm{kg} / \mathrm{m}^{3}$ & Konzentration im Kläranlagenablauf \\ — printed p.48', verification_note='md-verified 2026-09-05 (§7.3.2.2 Gl. (14), printed p.48 — printed with a ≤ B_R,e,zul condition attached) [VC]', verified_at=now() where id='626077ea-6c5a-4cf5-b10b-63836e0419b8' and verification_status <> 'verified_against_standard';
-- A1022-28 Gl.15 → e_0
update public.equations set verification_status='verified_against_standard', verification_quote='Daraus ergibt sich als Bestimmungsgleichung für die zulässige Entlastungsrate allgemein | e_{0} \leq\left(B_{R, e, \mathrm{zul}}-V_{R, \mathrm{aM}} \cdot C_{K \mathrm{~A}}\right) /\left(V_{R, \mathrm{aM}} C_{e}-V_{R, \mathrm{aM}} \cdot C_{K \mathrm{~A}}\right) \cdot 100 \text { in \% } \tag{15} — printed p.49', verification_note='md-verified 2026-09-05 (§7.3.2.2 Gl. (15), printed p.49 — printed as an inequality; the encoded formula carries the relational operator (see STAGED)) [VC]', verified_at=now() where id='a5bd51eb-1d34-4970-b633-68f8935a8ce9' and verification_status <> 'verified_against_standard';
-- A1022-28 Gl.16 → B_R_e_zul_CSB
update public.equations set verification_status='verified_against_standard', verification_quote='Für die Ermittlung des erforderlichen Gesamtspeichervolumens wird auf die in Arbeitsblatt ATVA 128:1992 für den CSB abgeleitete Zielsetzung zurückgegriffen. | B_{\mathrm{R}, \mathrm{e}, \mathrm{zu}, \mathrm{CSB}}=V_{\mathrm{R}, \mathrm{aM}} \cdot C_{\mathrm{R}, \mathrm{CSB}} \quad \text { in } \mathrm{kg} /(\mathrm{ha} \cdot \mathrm{a}) \tag{16} | $C_{\mathrm{R}, \mathrm{CSB}}$ & $\mathrm{g} / \mathrm{l}$ & mittlere jährliche CSB-Konzentration im Regenwasserabfluss \\ $B_{\mathrm{R}, \mathrm{e}, \mathrm{zu}, \mathrm{CSB}}$ & $\mathrm{kg} / \mathrm{a}$ & zulässiger jährlicher Stoffaustrag CSB durch Regenwasserabfluss — printed p.49', verification_note='md-verified 2026-09-05 (§7.3.2.2 Gl. (16), printed p.49) [VC]', verified_at=now() where id='a39c4e42-db13-408a-adb9-ca194128f5d8' and verification_status <> 'verified_against_standard';
-- A1022-28 Gl.17 → e_0
update public.equations set verification_status='verified_against_standard', verification_quote='Mit der mittleren Konzentration im Regenwasserabfluss $C_{R, \mathrm{CSB}}$ von $107 \mathrm{mg} / \mathrm{l}$ resultiert ein Wert $B_{\mathrm{R}, \mathrm{e}, \mathrm{zul}, \mathrm{CSB}}$ von $600 \mathrm{~kg} /(\mathrm{ha} \cdot \mathrm{a})$. In Verbindung mit Gl. (16) ergibt sich als Bestimmungsgleichung für $e_{0}$ : | e_{0} \leq\left(C_{R, C S B}-C_{K A, C S B}\right) /\left(C_{e, C S B}-C_{K A, C S B}\right) \cdot 100 \text { in } \% \tag{17} — printed p.49', verification_note='md-verified 2026-09-05 (§7.3.2.2 Gl. (17), printed p.49 — printed as an inequality; the encoded formula carries the relational operator (see STAGED)) [VC]', verified_at=now() where id='46fb523a-2e8f-4f8e-b61b-ff4888a76ea4' and verification_status <> 'verified_against_standard';
