-- A1022-33 Gl.24 → m
update public.equations set verification_status='verified_against_standard', verification_quote='Die bauwerksbezogene Ermittlung des mittleren Mischverhältnisses $m$ im Nachweisverfahren ist in 8.4.5.1 beschrieben. In Bezug auf Einzelbauwerke kann es mit den bauwerksbezogenen Kenngrößen nach GL. (24) abgeschätzt werden. | m=\left(Q_{\mathrm{R}, \mathrm{e}}+Q_{\mathrm{R}, \mathrm{Tr}}\right) / Q_{\mathrm{T}, \mathrm{aM}} \tag{24} — printed p.54', verification_note='md-verified 2026-09-05 (§7.3.4.2 Gl. (24), printed p.54 — identical to Gl. (B.13) p.88, both printed (see STAGED)) [VC]', verified_at=now() where id='89404ab0-4b15-4544-a486-4d25a0f7edff' and verification_status <> 'verified_against_standard';
