-- A1022-33 Gl.26 → Q_Dr
update public.equations set verification_status='verified_against_standard', verification_quote='Der mindestens weiterzuführende Abfluss $Q_{\mathrm{Dr}}$ vor Anspringen der Entlastung als „kritischer Mischwasserabfluss $Q_{\text {krit }}{ }^{\prime \prime}$ ergibt sich aus den maßgebenden Abflusswerten im Direkteinzugsgebiet des Regenüberlaufs und allen oberhalb liegenden Drosselabflüssen nach GL. (26). | Q_{\mathrm{Dr}} \geq Q_{\mathrm{T}, \mathrm{aM}}+Q_{\mathrm{R}, \mathrm{krit}}+\sum Q_{\mathrm{Dr}, \mathrm{i}} \quad \text { in } \mathrm{l} / \mathrm{s} \tag{26} | \hline $Q_{\mathrm{T}, \mathrm{aM}}$ & $\mathrm{l} / \mathrm{s}$ & Trockenwetterabfluss (Jahresmittelwert) aus dem Direkteinzugsgebiet des Regenüberlaufs \\ \hline $Q_{\mathrm{R}, \text { krit }}$ & l/s & kritischer Regenabfluss aus dem Direkteinzugsgebiet $\left(Q_{\mathrm{R}, \text { krit }}=r_{\text {krit }} \cdot A_{\mathrm{b}, \mathrm{a}} \mathrm{inl} / \mathrm{s}\right.$; siehe Anhang B, Unterabschnitt B.1.3) \\ \hline $\Sigma Q_{\mathrm{Dr}, \mathrm{i}}$ & l/s & Summe aller unmittelbar von oberhalb zufließenden Drosselabflüsse \\ — printed p.55', verification_note='md-verified 2026-09-05 (§7.3.4.5 Gl. (26), printed p.55 — printed as an inequality; the encoded formula carries the relational operator (see STAGED)) [VC]', verified_at=now() where id='29c268ef-33c1-4b28-8269-c06d8465729f' and verification_status <> 'verified_against_standard';
-- A1022-33 Gl.27 → m_Rue
update public.equations set verification_status='verified_against_standard', verification_quote='Für den nach GL. (26) ermittelten Drosselabfluss ist das Mindestmischverhältnis $m_{\mathrm{RU}}$ nachzuweisen. Der dafür maßgebende Wert m errechnet sich abhängig von der Verschmutzung des Trockenwetter- abflusses analog 7.3.4.2. Ergibt sich bei Anspringen des Überlaufs zwischen Regen- und Trockenwetteranteil im kritischen Mischwasserabfluss nach GI. (27) ein kleineres Mischverhältnis ( $m_{\mathrm{Ru}}<m$ ) ist der Drosselabfluss entsprechend GL. (28) zu erhöhen. | m_{\mathrm{RU}}=\left(Q_{\mathrm{Dr}}-Q_{\mathrm{T}, \mathrm{aM}}\right) / Q_{\mathrm{T}, \mathrm{aM}} \tag{27} — printed p.55', verification_note='md-verified 2026-09-05 (§7.3.4.5 Gl. (27), printed p.55) [VC]', verified_at=now() where id='ef227cf7-ff9c-493f-a503-82ba965050bb' and verification_status <> 'verified_against_standard';
-- A1022-33 Gl.28 → Q_Dr
update public.equations set verification_status='verified_against_standard', verification_quote='Der Mindestdrosselabfluss errechnet sich aus Gl. (25) zu: | Q_{\mathrm{Dr}} \geq\left(m_{\mathrm{RU}}+1\right) \cdot Q_{\mathrm{T}, \mathrm{aM}} \quad \text { in l/s } \tag{28} | Dieser Wert ist maßgebend, wenn er den Wert nach GL. (26) übersteigt. — printed p.55', verification_note='md-verified 2026-09-05 (§7.3.4.5 Gl. (28), printed p.55 — printed as an inequality; the encoded formula carries the relational operator (see STAGED)) [VC]', verified_at=now() where id='0708808f-84f8-4b82-82f0-a8dda7977bee' and verification_status <> 'verified_against_standard';
-- A1022-36 Gl.22 → m
update public.equations set verification_status='verified_against_standard', verification_quote='Für jedes Regenüberlaufbecken ist zu überprüfen, ob im langjährigen Mittel ein Mindestmischverhältnis $m$ nach GL. (22) eingehalten wird. Liegt die mittlere CSB-Konzentration im Trockenwetterabfluss über $600 \mathrm{mg} / \mathrm{l}$, ist das Mindestmischverhältnis m nach Gl. (23) zu erhöhen. | m \geq 7 & \text { für } & C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}} \leq 600 \mathrm{mg} / \mathrm{l} \\ m \geq\left(C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}-180\right) / 60 & \text { für } & C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}>600 \mathrm{mg} / \mathrm{l} \tag{23} — printed p.53', verification_note='md-verified 2026-09-05 (§7.3.4.2 Gl. (22), printed p.53) [VC]', verified_at=now() where id='d2d1bf8b-5e93-4ad8-963a-d297c89b2d14' and verification_status <> 'verified_against_standard';
-- A1022-36 Gl.23 → m
update public.equations set verification_status='verified_against_standard', verification_quote='Für jedes Regenüberlaufbecken ist zu überprüfen, ob im langjährigen Mittel ein Mindestmischverhältnis $m$ nach GL. (22) eingehalten wird. Liegt die mittlere CSB-Konzentration im Trockenwetterabfluss über $600 \mathrm{mg} / \mathrm{l}$, ist das Mindestmischverhältnis m nach Gl. (23) zu erhöhen. | m \geq 7 & \text { für } & C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}} \leq 600 \mathrm{mg} / \mathrm{l} \\ m \geq\left(C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}-180\right) / 60 & \text { für } & C_{\mathrm{T}, \mathrm{aM}, \mathrm{CSB}}>600 \mathrm{mg} / \mathrm{l} \tag{23} — printed p.53', verification_note='md-verified 2026-09-05 (§7.3.4.2 Gl. (23), printed p.53 — identical encoded formula to Gl.22 (see STAGED)) [VC]', verified_at=now() where id='70ebb0c4-2db9-4405-85ef-da863172666c' and verification_status <> 'verified_against_standard';
